/**
 * components/shared/SharedDashboardsPage.js. Manage tokenized agency dashboard links.
 *
 * Admin and creator both create/edit "shared dashboards": a public read-only view
 * of a creator's campaigns and/or payments for one agency, reachable without login
 * at nysterys.com/shared/#t={token}. Admin sees every creator's dashboards; creator
 * sees only their own (RLS-scoped on creator_id). Scope (campaigns/payments/both)
 * and campaign selection (all-for-agency or a specific list) gate what the agency
 * sees; links can carry an expiry and be deactivated to revoke access instantly.
 *
 * @security The token is the only credential. The agency endpoint reads it as a
 *           Bearer and the URL keeps it in the fragment so it is never sent to the
 *           server as a query param. Deactivate (is_active=false) revokes access
 *           immediately. @see docs/CODEBASE.md (agency dashboard) + the
 *           agency-dashboard edge function.
 */
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { supabase } from '../../lib/supabase';
import { ExternalLinkIcon } from './Icon';
import { fmtDate, todayYMD, localYMD } from '../../utils/format';
import { openTab } from '../../utils/openPopup';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { mutate } from '../../utils/mutate';
import { useConfirm } from './ConfirmDialog';
import { useToast } from './Toast';
import { humanizeError } from '../../utils/errors';
import Feedback from './Feedback';
import EmptyState from './EmptyState';
import { useCreators } from '../../hooks/useCreators';
import RateCardEditor from './RateCardEditor';
import { campaignLabel } from '../../utils/campaignLabel';
import { DB_DATE_MAX } from '../../utils/dbLimits';
import Modal, { ModalClose } from './Modal';
import Field from './Field';
import Loading from './Loading';
import SubmitButton from './SubmitButton';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';

const BASE_URL = 'https://nysterys.com/shared/#t=';

const SCOPE_OPTIONS = [
  { value: 'campaigns_and_payments', label: 'Campaigns & Payments', desc: 'Full deliverable details and payment status' },
  { value: 'campaigns_only',         label: 'Campaigns Only',       desc: 'Deliverables and performance stats, no financials' },
  { value: 'payments_only',          label: 'Payments Only',        desc: 'Invoice status and amounts, no financials' },
  // A prospect link: no agency, no campaigns, just the creator's default rates.
  // chk_prospect_link_is_rates_only forces any agency-less link into this scope.
  { value: 'rates_only',             label: 'Rates Only',           desc: 'For a prospect who has asked for rates. No campaigns or payments' },
];

const SCOPE_LABELS = Object.fromEntries(SCOPE_OPTIONS.map(o => [o.value, o.label]));

/**
 * True when a chosen expiry is a day that has already gone by, in the local calendar.
 *
 * @gotcha the form field is a date-only string and `todayYMD()` is the local date, so this is
 *         a string comparison, never a Date one. `new Date(expiresAt + 'T00:00:00') < new
 *         Date()` refused TODAY from one second after midnight, under a message that promised
 *         today was allowed. @see .claude/rules/hub-data.md
 */
function isExpiryInPast(expiresAt) {
  return !!expiresAt && expiresAt < todayYMD();
}

/**
 * The instant a link chosen to expire on `ymd` actually dies: the last second of that day in
 * the ADMIN'S OWN zone. A chosen day means the whole of that day as she experiences it.
 *
 * @gotcha never `ymd + 'T23:59:59Z'`, which is 19:59 local in New York, so a link set for
 *         today and created at 22:30 was born expired and the row rendered a red Expired
 *         badge over a date that still read today. `expires_at` is timestamptz: a day is not
 *         an instant until a zone is applied, and the only zone that matches the promise the
 *         picker makes is the local one. A row already in the database keeps the UTC
 *         meaning it was written with until it is next edited: no backfill, on purpose.
 */
function expiryInstant(ymd) {
  const [y, m, d] = ymd.split('-').map(Number);
  // Millis trimmed so the stored shape stays the one the column already holds everywhere.
  return new Date(y, m - 1, d, 23, 59, 59).toISOString().replace('.000Z', 'Z');
}

/**
 * Shared dashboards manager. @see file header.
 * @param {?string} props.profileId - creator's uuid; scopes the list + new-link creator.
 * @param {boolean} props.isAdmin - true → all creators + delete; false → own only.
 */
export default function SharedDashboardsPage({ profileId, isAdmin }) {
  const askConfirm = useConfirm();
  const toast = useToast();
  const { options: statusOptions, loading: vocabLoading } = useStatusOptions();
  const [dashboards,  setDashboards]  = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  // Why a list read needs a third state: an empty result and a failed read look
  // identical downstream, and this page's empty state makes a claim about who
  // has access.
  const [loadError,   setLoadError]   = useState(null);
  const [agencies,    setAgencies]    = useState([]);
  const [agenciesError, setAgenciesError] = useState(null);
  const { creators }                  = useCreators(isAdmin);  // admin only
  const [showModal,   setShowModal]   = useState(false);
  const [modalStep,   setModalStep]   = useState('form'); // 'form' | 'success'
  const [editingId,   setEditingId]   = useState(null);  // null = create, string = edit
  const [form,        setForm]        = useState(null);
  const [availCamps,  setAvailCamps]  = useState([]);
  const [campsLoading,setCampsLoading]= useState(false);
  const [campsErr,   setCampsErr]    = useState(null);
  const [saving,      setSaving]      = useState(false);
  const [saveError,   setSaveError]   = useState('');
  const [newToken,    setNewToken]    = useState('');
  const [copiedId,    setCopiedId]    = useState(null);
  const [openMenuId,  setOpenMenuId]  = useState(null);
  // Viewport coords of the trigger, captured at click time. The menu is a portal
  // (see OverflowMenu) so it cannot inherit position from the clipped row.
  const [menuPos,     setMenuPos]     = useState({ top: 0, right: 0 });
  // The link whose own rate card is open. A prospect is not an agency, so their
  // bespoke pricing hangs off the link itself. @see CLAUDE.md "Agency rate cards"
  const [ratesFor,    setRatesFor]    = useState(null);
  const menuRef = useRef(null);

  const blankForm = useCallback(() => ({
    creatorId: isAdmin ? '' : profileId,
    name:      '',
    agencyId:  '',
    scope:     'campaigns_and_payments',
    allCampaigns: true,
    selectedIds:  [],
    expiresAt:    '',
    showRates:       false,
    useDefaultRates: false,
  }), [isAdmin, profileId]);

  /**
   * Fetch the link list.
   *
   * @gotcha a failed read must NOT fall through to `data || []`. The empty
   *         state below reads "No shared dashboards yet", so a refused read
   *         renders as the confident statement that no agency holds a link, on
   *         the one page whose job is to say what access has been handed out.
   */
  const load = useCallback(async () => {
    begin();
    setLoadError(null);
    let q = supabase
      .from('shared_dashboards')
      .select('id, creator_id, agency_id, name, scope, show_rates, use_default_rates, campaign_ids, is_active, created_at, last_accessed_at, access_count, token, expires_at, agencies(id, name), profiles!creator_id(full_name, creator_name)')
      .order('created_at', { ascending: false });
    if (!isAdmin) q = q.eq('creator_id', profileId);
    const { data, error } = await q;
    if (error) { setLoadError(humanizeError(error)); setDashboards([]); end(); return; }
    setDashboards(data || []);
    end();
  }, [isAdmin, profileId, begin, end]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (!openMenuId) return;
    function handleClick(e) {
      if (!e.target.closest('[data-overflow-menu]')) setOpenMenuId(null);
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [openMenuId]);

  // Agencies feed the create modal's picker and nothing else, so a failure here
  // is reported inside that modal rather than over the whole page: the list of
  // existing links is still readable and still revocable without it. Silently
  // empty, it read as "we have no agencies" and blocked creating a link with no
  // explanation.
  useEffect(() => {
    supabase.from('agencies').select('id, name').eq('is_active', true).order('name')
      .then(({ data, error }) => {
        setAgenciesError(error ? humanizeError(error) : null);
        setAgencies(data || []);
      });
  }, []);

  // Reload available campaigns whenever creator or agency changes in the form.
  // Both creator and agency must be chosen before the campaign list populates;
  // Cancelled campaigns are filtered out so they can never be shared.
  useEffect(() => {
    if (!form) return;
    if (!form.creatorId || !form.agencyId) { setAvailCamps([]); return; }
    const cancelledId = (statusOptions.campaign || []).find(o => o.value === 'Cancelled')?.id;
    setCampsLoading(true);
    // Fails closed, unlike the calendar, because the consequence here is a link a client holds
    // and an admin who waits sixty seconds loses nothing. `if (cancelledId) q = q.neq(...)`
    // dropped the filter and ran the query anyway, so an unresolved id offered the cancelled
    // campaign for sharing.
    if (!cancelledId) {
      setAvailCamps([]);
      if (vocabLoading) return;
      setCampsErr({ tone: 'error', title: 'Cannot list campaigns', body: 'The status list did not load, so cancelled campaigns cannot be filtered out. Try again before creating a link.' });
      setCampsLoading(false);
      return;
    }
    let q = supabase
      .from('campaigns')
      .select('id, campaign_name, display_name, campaign_start_date, status_id')
      .eq('creator_profile_id', form.creatorId)
      .eq('agency_id', form.agencyId)
      .order('campaign_start_date', { ascending: false });
    q = q.neq('status_id', cancelledId);
    setCampsErr(null);
    q.then(({ data, error }) => {
      // Reported inside the create modal, not on the page: this list only fills
      // the campaign picker, and the existing links stay readable and revocable
      // without it. Same split B-08 made for the agencies read in this file.
      if (error) setCampsErr(humanizeError(error));
      setAvailCamps(data || []);
      setCampsLoading(false);
    });
  }, [form?.creatorId, form?.agencyId, statusOptions, vocabLoading]);

  function openModal() {
    setEditingId(null);
    setForm(blankForm());
    setAvailCamps([]);
    setSaveError('');
    setModalStep('form');
    setNewToken('');
    setShowModal(true);
  }

  function openEditModal(d) {
    setEditingId(d.id);
    setForm({
      creatorId:    d.creator_id,
      name:         d.name,
      agencyId:     d.agency_id,
      scope:        d.scope,
      allCampaigns: !d.campaign_ids,
      selectedIds:  d.campaign_ids || [],
      // localYMD of the stored INSTANT, never a slice of it: the UTC day is tomorrow all
      // evening in New York, so the edit form opened on the wrong day and saving moved it.
      expiresAt:    d.expires_at ? localYMD(new Date(d.expires_at)) : '',
      showRates:       !!d.show_rates,
      useDefaultRates: !!d.use_default_rates,
      _agencyName:  d.agencies?.name || '',
      _creatorName: d.profiles?.creator_name || d.profiles?.full_name || '',
    });
    setAvailCamps([]);
    setSaveError('');
    setModalStep('form');
    setNewToken('');
    setShowModal(true);
  }

  function closeModal() {
    setShowModal(false);
    setForm(null);
    setEditingId(null);
  }

  function setField(key, val) {
    setForm(prev => {
      const next = { ...prev, [key]: val };
      if (key === 'creatorId' || key === 'agencyId') {
        next.selectedIds = [];
      }
      return next;
    });
  }

  function toggleCampaign(id) {
    setForm(prev => {
      const has = prev.selectedIds.includes(id);
      return {
        ...prev,
        selectedIds: has
          ? prev.selectedIds.filter(x => x !== id)
          : [...prev.selectedIds, id],
      };
    });
  }

  /**
   * Validate + INSERT a new shared dashboard, then advance to the success step
   * showing the generated token URL. Errors arrive already humanized from mutate().
   * @gotcha expires_at is the end of the chosen day in the ADMIN'S zone, built by
   *         expiryInstant and never concatenated; campaign_ids=null means "all
   *         campaigns for this agency" (distinct from an empty array).
   */
  async function create() {
    const ratesOnly = form.scope === 'rates_only';
    if (!form.name.trim())  { setSaveError('Dashboard name is required.'); return; }
    // A prospect link has no agency and no campaigns by definition, so neither
    // is required. The DB enforces the same shape via chk_prospect_link_is_rates_only.
    if (!ratesOnly && !form.agencyId) { setSaveError('Select an agency.'); return; }
    if (isAdmin && !form.creatorId) { setSaveError('Select a creator.'); return; }
    if (!ratesOnly && !form.allCampaigns && form.selectedIds.length === 0) {
      setSaveError('Select at least one campaign, or choose "All campaigns".'); return;
    }
    if (isExpiryInPast(form.expiresAt)) {
      setSaveError('Expiry date must be today or in the future.'); return;
    }
    setSaveError('');
    setSaving(true);
    const { data, error } = await mutate(supabase
      .from('shared_dashboards')
      .insert({
        creator_id:   form.creatorId,
        // A rates-only prospect link has no agency: chk_prospect_link_is_rates_only
        // rejects an agency-less link in any other scope, and an agency here would
        // make it an agency dashboard rather than a prospect one.
        agency_id:    form.scope === 'rates_only' ? null : form.agencyId,
        name:         form.name.trim(),
        scope:        form.scope,
        show_rates:        form.scope === 'rates_only' ? true : form.showRates,
        use_default_rates: form.scope === 'rates_only' ? true : form.useDefaultRates,
        campaign_ids: form.allCampaigns ? null : form.selectedIds,
        expires_at:   form.expiresAt ? expiryInstant(form.expiresAt) : null,
      })
      .select('id, token')
      .single());
    setSaving(false);
    if (error) { setSaveError(error); return; }
    setNewToken(data.token);
    setModalStep('success');
    load();
  }

  /**
   * Validate + UPDATE an existing dashboard's name/scope/campaigns/expiry. Creator
   * and agency are immutable after creation (rendered read-only in the modal).
   */
  async function update() {
    if (!form.name.trim()) { setSaveError('Dashboard name is required.'); return; }
    if (form.scope !== 'rates_only' && !form.allCampaigns && form.selectedIds.length === 0) {
      setSaveError('Select at least one campaign, or choose "All campaigns".'); return;
    }
    if (isExpiryInPast(form.expiresAt)) {
      setSaveError('Expiry date must be today or in the future.'); return;
    }
    setSaveError('');
    setSaving(true);
    const { error } = await mutate(supabase
      .from('shared_dashboards')
      .update({
        name:         form.name.trim(),
        scope:        form.scope,
        show_rates:        form.scope === 'rates_only' ? true : form.showRates,
        use_default_rates: form.scope === 'rates_only' ? true : form.useDefaultRates,
        campaign_ids: form.allCampaigns ? null : form.selectedIds,
        expires_at:   form.expiresAt ? expiryInstant(form.expiresAt) : null,
      })
      .eq('id', editingId));
    setSaving(false);
    if (error) { setSaveError(error); return; }
    closeModal();
    load();
  }

  /**
   * Flip is_active. @security setting false revokes the token's access at once.
   *
   * @gotcha the row is updated only AFTER the write lands, deliberately NOT
   *         optimistically as CalendarPage's drag does. A revoke that was
   *         refused is the one thing that must never render as done, and an
   *         optimistic flip asserts exactly that for the length of the round
   *         trip. On failure the row keeps showing the state the database
   *         actually holds, and the toast says why.
   */
  async function toggleActive(id, current) {
    const { error } = await mutate(
      supabase.from('shared_dashboards').update({ is_active: !current }).eq('id', id)
    );
    if (error) { toast[error.tone || 'error'](error); return; }
    setDashboards(prev => prev.map(d => d.id === id ? { ...d, is_active: !current } : d));
  }

  /** Delete a link and its access log. Same after-the-write rule as toggleActive. */
  async function deleteDashboard(id, name) {
    if (!(await askConfirm({ title: `Delete "${name}"?`, body: 'The access log will be removed too. This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('shared_dashboards').delete().eq('id', id));
    if (error) { toast[error.tone || 'error'](error); return; }
    setDashboards(prev => prev.filter(d => d.id !== id));
  }

  function copyUrl(token, id) {
    const url = BASE_URL + token;
    navigator.clipboard.writeText(url).then(() => {
      setCopiedId(id);
      setTimeout(() => setCopiedId(null), 2000);
    });
  }

  /**
   * Open the agency-facing dashboard in an ordinary tab.
   *
   * @gotcha A tab, NOT openPopup. A chrome-less popup has no back button, so
   *         opening an invoice from inside the preview was a dead end, and a
   *         window.open() from within a popup yields another popup instead of
   *         a tab. A tab is also the faithful preview: an agency opens the
   *         shared link in a normal window, at their own size, above the
   *         dashboard's 768px mobile breakpoint.
   */
  function preview(token) {
    openTab(BASE_URL + token);
  }

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="page">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24, gap: 16 }}>
        <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, letterSpacing: '0.04em' }}>
          Shared Dashboards<Refreshing on={refreshing} />
        </h1>
        <button className="btn btn-primary btn-sm" onClick={openModal}>
          + New Dashboard
        </button>
      </div>

      {loading ? (
        <Loading />
      ) : loadError ? (
        // Between loading and empty, never folded into either. Retry rather
        // than a page reload, since load() is already a useCallback and the
        // failure this covers is usually transient.
        <>
          <Feedback value={loadError} />
          <button className="btn btn-secondary btn-sm" style={{ marginTop: 12 }} onClick={load}>
            Try again
          </button>
        </>
      ) : dashboards.length === 0 ? (
        <EmptyState
          icon={<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71"/></svg>}
          title="No shared dashboards yet"
          text="Create one to share campaign status or payment info with an agency." />
      ) : (
        <div className="table-wrap">
          <table className="pinned-actions">
            <thead>
              <tr>
                <th scope="col">Name</th>
                {isAdmin && <th scope="col">Creator</th>}
                <th scope="col">Agency</th>
                <th scope="col" style={{ textAlign: 'right' }}>Views</th>
                <th scope="col">Last Seen</th>
                <th scope="col">Expires</th>
                <th scope="col" style={{ width: 1 }}></th>
              </tr>
            </thead>
            <tbody>
              {dashboards.map(d => {
                const campMeta = d.campaign_ids
                  ? d.campaign_ids.length + ' campaign' + (d.campaign_ids.length !== 1 ? 's' : '')
                  : 'All campaigns';
                const scopeMeta = SCOPE_LABELS[d.scope] || d.scope;
                return (
                  <tr key={d.id}>
                    <td style={{ minWidth: 200 }}>
                      <div style={{ fontWeight: 500 }}>{d.name}</div>
                      <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 3, display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
                        <span>{scopeMeta}</span>
                        <span style={{ color: 'var(--dim)' }}>·</span>
                        <span>{campMeta}</span>
                        {!d.is_active && (
                          <>
                            <span style={{ color: 'var(--dim)' }}>·</span>
                            <span style={{ color: 'var(--muted)', fontWeight: 500, letterSpacing: '0.5px', textTransform: 'uppercase', fontSize: 9 }}>Inactive</span>
                          </>
                        )}
                      </div>
                    </td>
                    {isAdmin && (
                      <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                        {d.profiles?.creator_name || d.profiles?.full_name || '—'}
                      </td>
                    )}
                    <td style={{ fontSize: 13 }}>{d.agencies?.name || '—'}</td>
                    <td style={{ fontVariantNumeric: 'tabular-nums', fontSize: 13, textAlign: 'right', fontWeight: d.access_count >= 50 ? 500 : 300, color: d.access_count >= 50 ? 'var(--white)' : 'var(--muted)' }}>
                      {d.access_count}
                    </td>
                    <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                      {d.last_accessed_at ? fmtDate(d.last_accessed_at) : 'Never'}
                    </td>
                    <td style={{ fontSize: 12 }}>
                      <ExpiryCell expiresAt={d.expires_at} />
                    </td>
                    <td style={{ whiteSpace: 'nowrap' }}>
                      <div style={{ display: 'flex', gap: 4, alignItems: 'center', justifyContent: 'flex-end' }}>
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => copyUrl(d.token, d.id)}
                          title="Copy shareable URL"
                        >
                          {copiedId === d.id ? '✓ Copied' : 'Copy URL'}
                        </button>
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => preview(d.token)}
                          title="Preview dashboard in a new tab"
                        >
                          Preview <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} />
                        </button>
                        <div style={{ position: 'relative' }} data-overflow-menu ref={openMenuId === d.id ? menuRef : null}>
                          <button
                            className="btn btn-ghost btn-sm btn-icon"
                            style={{ fontSize: 16, lineHeight: 1, padding: '4px 8px', letterSpacing: 0, textTransform: 'none' }}
                            onClick={(e) => {
                              const r = e.currentTarget.getBoundingClientRect();
                              setMenuPos({ top: r.bottom + 4, right: window.innerWidth - r.right });
                              setOpenMenuId(openMenuId === d.id ? null : d.id);
                            }}
                            title="More actions"
                            aria-label="More actions"
                          >
                            ⋯
                          </button>
                          {openMenuId === d.id && (
                            <OverflowMenu pos={menuPos}>
                              <MenuButton onClick={() => { openEditModal(d); setOpenMenuId(null); }}>Edit</MenuButton>
                              {isAdmin && d.show_rates && (
                                <MenuButton onClick={() => { setRatesFor(d); setOpenMenuId(null); }}>Rates for this link</MenuButton>
                              )}
                              <MenuButton onClick={() => { toggleActive(d.id, d.is_active); setOpenMenuId(null); }}>
                                {d.is_active ? 'Deactivate' : 'Activate'}
                              </MenuButton>
                              {isAdmin && (
                                <MenuButton danger onClick={() => { deleteDashboard(d.id, d.name); setOpenMenuId(null); }}>Delete</MenuButton>
                              )}
                            </OverflowMenu>
                          )}
                        </div>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Create modal ── */}
      {ratesFor && (
        <>
          {/* Click-away closes it. A .detail-panel-overlay, not a .modal-overlay:
              the app-wide backdrop-close ban protects unsaved form state, and
              this editor saves on blur. */}
          <div className="detail-panel-overlay" onClick={() => setRatesFor(null)} />
          <RateCardEditor
            agencyId={null}
            dashboardId={ratesFor.id}
            lockCreatorId={ratesFor.creator_id}
            agencyName={ratesFor.name}
            onClose={() => setRatesFor(null)}
          />
        </>
      )}

      {showModal && form && (
        <Modal
          title={modalStep === 'success' ? 'Dashboard Created' : editingId ? 'Edit Dashboard' : 'New Shared Dashboard'}
          size="md"
          onClose={closeModal}
          showClose={false}
        >
            {modalStep === 'success' ? (
              <SuccessStep token={newToken} onCopy={() => copyUrl(newToken, '__new')} onPreview={() => preview(newToken)} onClose={closeModal} copiedId={copiedId} />
            ) : (
              <>
                <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                  {/* Above the fields it explains: with no agency list the
                      picker below is empty, which otherwise reads as "we have
                      no agencies". Only on create, since editing shows the
                      agency as read-only text. */}
                  {!editingId && agenciesError && <Feedback value={agenciesError} />}

                  {/* Admin: creator: selector when creating, read-only when editing */}
                  {isAdmin && (
                    <Field label="Creator">{(id) => (<>
                      {editingId ? (
                        <div className="form-input" style={{ color: 'var(--muted)', cursor: 'default' }}>{form._creatorName || '—'}</div>
                      ) : (
                        <select id={id}
                          className="form-select"
                          value={form.creatorId}
                          onChange={e => setField('creatorId', e.target.value)}
                        >
                          <option value="">Select creator…</option>
                          {creators.map(c => (
                            <option key={c.id} value={c.id}>
                              {c.creator_name || c.full_name}
                            </option>
                          ))}
                        </select>
                      )}
                    </>)}</Field>
                  )}

                  <Field label="Dashboard Name">{(id) => (<>
                    <input id={id}
                      className="form-input"
                      type="text"
                      maxLength={120}
                      placeholder="e.g. BrandX Q2 2026: Campaigns"
                      value={form.name}
                      onChange={e => setField('name', e.target.value)}
                    />
                  </>)}</Field>

                  {/* A prospect link has no agency: it is sent to someone we
                      have not signed, and the DB rejects an agency on it. */}
                  {form.scope !== 'rates_only' && (
                  <Field label="Agency">{(id) => (<>
                    {editingId ? (
                      <div className="form-input" style={{ color: 'var(--muted)', cursor: 'default' }}>{form._agencyName || '—'}</div>
                    ) : (
                      <select id={id}
                        className="form-select"
                        value={form.agencyId}
                        onChange={e => setField('agencyId', e.target.value)}
                      >
                        <option value="">Select agency…</option>
                        {agencies.map(a => (
                          <option key={a.id} value={a.id}>{a.name}</option>
                        ))}
                      </select>
                    )}
                  </>)}</Field>
                  )}

                  <Field label="Scope">{(id) => (<>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 4 }}>
                      {SCOPE_OPTIONS.map(opt => (
                        <label key={opt.value} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, cursor: 'pointer' }}>
                          <input id={id}
                            type="radio"
                            name="scope"
                            value={opt.value}
                            checked={form.scope === opt.value}
                            onChange={() => setField('scope', opt.value)}
                            style={{ marginTop: 2, flexShrink: 0 }}
                          />
                          <div>
                            <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--white)' }}>{opt.label}</div>
                            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 1 }}>{opt.desc}</div>
                          </div>
                        </label>
                      ))}
                    </div>
                  </>)}</Field>

                  {/* Rates. A rates-only link is rates by definition, so the
                      switches disappear rather than sitting there inert. */}
                  {form.scope !== 'rates_only' && (
                    <div className="form-group">
                      <div className="form-label">Rates</div>
                      <label style={{ display: 'flex', alignItems: 'flex-start', gap: 10, cursor: 'pointer', marginTop: 4 }}>
                        <input
                          type="checkbox"
                          checked={form.showRates}
                          onChange={e => setField('showRates', e.target.checked)}
                          style={{ marginTop: 2, flexShrink: 0 }}
                        />
                        <div>
                          <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--white)' }}>Show a Rates tab</div>
                          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 1 }}>
                            This agency&apos;s own rate card for this creator. Set it up in Agency Setup &rarr; Rates.
                          </div>
                        </div>
                      </label>

                      {form.showRates && (
                        <label style={{ display: 'flex', alignItems: 'flex-start', gap: 10, cursor: 'pointer', marginTop: 10 }}>
                          <input
                            type="checkbox"
                            checked={form.useDefaultRates}
                            onChange={e => setField('useDefaultRates', e.target.checked)}
                            style={{ marginTop: 2, flexShrink: 0 }}
                          />
                          <div>
                            <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--white)' }}>Fall back to default rates</div>
                            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 1 }}>
                              If this agency has no card of its own, show the creator&apos;s default rather than an empty tab.
                            </div>
                          </div>
                        </label>
                      )}
                    </div>
                  )}

                  {/* No campaigns on a prospect link. */}
                  {form.scope !== 'rates_only' && (
                  <div className="form-group">
                    <div className="form-label">Campaign Selection</div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 4 }}>
                      <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' }}>
                        <input
                          type="radio"
                          name="campFilter"
                          checked={form.allCampaigns}
                          onChange={() => setField('allCampaigns', true)}
                        />
                        <span style={{ fontSize: 13, color: 'var(--white)' }}>All campaigns for this agency</span>
                      </label>
                      <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' }}>
                        <input
                          type="radio"
                          name="campFilter"
                          checked={!form.allCampaigns}
                          onChange={() => setField('allCampaigns', false)}
                        />
                        <span style={{ fontSize: 13, color: 'var(--white)' }}>Specific campaigns</span>
                      </label>
                    </div>

                    {!form.allCampaigns && (
                      <div style={{
                        marginTop: 10, border: '1px solid var(--border)', borderRadius: 6,
                        maxHeight: 200, overflowY: 'auto', background: 'var(--surface2)'
                      }}>
                        {!form.agencyId || (!isAdmin ? false : !form.creatorId) ? (
                          <div style={{ padding: '12px 14px', fontSize: 12, color: 'var(--muted)' }}>
                            Select {isAdmin && !form.creatorId ? 'a creator and ' : ''}an agency first.
                          </div>
                        ) : campsLoading ? (
                          <Loading style={{ padding: '12px 14px', fontSize: 12 }}>Loading campaigns…</Loading>
                        ) : campsErr ? (
                          <div style={{ padding: '12px 14px' }}><Feedback value={campsErr} /></div>
                        ) : availCamps.length === 0 ? (
                          <EmptyState variant="note" style={{ padding: '12px 14px' }} text="No campaigns found for this selection." />
                        ) : availCamps.map(c => (
                          <label key={c.id} style={{
                            display: 'flex', alignItems: 'center', gap: 10,
                            padding: '9px 14px', cursor: 'pointer', borderBottom: '1px solid var(--border)',
                          }}>
                            <input
                              type="checkbox"
                              checked={form.selectedIds.includes(c.id)}
                              onChange={() => toggleCampaign(c.id)}
                              style={{ flexShrink: 0 }}
                            />
                            <div style={{ minWidth: 0 }}>
                              <div title={campaignLabel(c)} style={{ fontSize: 12, fontWeight: 500, color: 'var(--white)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                {campaignLabel(c)}
                              </div>
                              <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 1 }}>
                                {(statusOptions.campaign || []).find(o => o.id === c.status_id)?.value} · {fmtDate(c.campaign_start_date)}
                              </div>
                            </div>
                          </label>
                        ))}
                      </div>
                    )}
                  </div>
                  )}

                  <Field label="Link Expires">{(id) => (<>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      <input id={id}
                        className="form-input"
                        type="date" max={DB_DATE_MAX}
                        // todayYMD, never toISOString: the UTC date is tomorrow after 8pm in
                        // New York, so the picker refused to offer today.
                        min={todayYMD()}
                        value={form.expiresAt}
                        onChange={e => setField('expiresAt', e.target.value)}
                        style={{ flex: 1 }}
                      />
                      {form.expiresAt && (
                        <button
                          type="button"
                          className="btn btn-ghost btn-sm"
                          onClick={() => setField('expiresAt', '')}
                          title="Remove expiry: link will never expire"
                        >
                          No expiry
                        </button>
                      )}
                    </div>
                    <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6 }}>
                      Leave blank for a permanent link. Agencies see a notice when fewer than 7 days remain.
                    </div>
                  </>)}</Field>

                  <Feedback value={saveError} />
                </div>

                <div className="modal-footer">
                  <ModalClose className="btn btn-secondary" disabled={saving}>Cancel</ModalClose>
                  <SubmitButton saving={saving} className="btn btn-primary" onClick={editingId ? update : create} disabled={saving}>{editingId ? 'Save Changes' : 'Create Dashboard'}</SubmitButton>
                </div>
              </>
            )}
        </Modal>
      )}
    </div>
  );
}

/**
 * The row overflow menu, rendered into document.body.
 *
 * @param {{top:number, right:number}} pos - viewport coords from the trigger's rect
 *
 * @gotcha This MUST be a portal. Positioned absolutely inside the row it was
 *         clipped away entirely: `.table-wrap` sets `overflow-x: auto`, and CSS
 *         forces the other axis to `auto` too, so the wrapper is a clipping
 *         container. With few rows the menu opens BELOW the wrapper's bottom
 *         edge and simply never appears, which reads as "the button does
 *         nothing" rather than as a visual bug.
 * @gotcha position:fixed coords come from the trigger's rect at click time, so
 *         the menu closes on scroll rather than drifting away from its button.
 */
function OverflowMenu({ pos, children }) {
  useEffect(() => {
    const close = () => document.dispatchEvent(new MouseEvent('mousedown'));
    window.addEventListener('scroll', close, true);
    return () => window.removeEventListener('scroll', close, true);
  }, []);

  return createPortal(
    <div
      data-overflow-menu
      style={{
        position: 'fixed', top: pos.top, right: pos.right, zIndex: 400,
        background: 'var(--surface)', border: '1px solid var(--border2)',
        borderRadius: 'var(--radius)', minWidth: 148,
        boxShadow: 'var(--shadow-md)', overflow: 'hidden',
      }}
    >
      {children}
    </div>,
    document.body
  );
}

function MenuButton({ onClick, danger, children }) {
  const [hovered, setHovered] = useState(false);
  return (
    <button
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        display: 'block', width: '100%', padding: '9px 14px',
        background: hovered ? 'var(--surface2)' : 'none',
        border: 'none', borderBottom: '1px solid var(--border)',
        color: hovered ? (danger ? 'var(--red)' : 'var(--white)') : (danger ? 'var(--red)' : 'var(--muted)'),
        fontSize: 12, textAlign: 'left', cursor: 'pointer',
        fontFamily: 'var(--font-body)', transition: 'background 120ms, color 120ms',
      }}
    >
      {children}
    </button>
  );
}

/**
 * Expiry cell: em-dash for no expiry, struck-through "Expired" badge once past,
 * else the date with a colored dot + "Nd left" countdown when within 7 days
 * (orange ≤1 day, amber ≤7).
 *
 * @gotcha the badge and the printed date both come off the stored INSTANT read in the
 *         local zone. `expiresAt.slice(0, 10)` is the UTC day, so between 8pm and
 *         midnight in New York the cell put a red Expired badge over a date that still
 *         read today. One clock for both halves, or they contradict each other.
 */
function ExpiryCell({ expiresAt }) {
  if (!expiresAt) {
    return <span style={{ color: 'var(--dim)' }}>—</span>;
  }
  const exp = new Date(expiresAt);
  const now = new Date();
  const msLeft = exp - now;
  const dateStr = fmtDate(exp);

  if (msLeft < 0) {
    return (
      <span>
        <span className="badge badge-red-soft" style={{ fontSize: 10, padding: '1px 6px' }}>Expired</span>
        <span style={{ display: 'block', color: 'var(--dim)', fontSize: 11, marginTop: 3, textDecoration: 'line-through' }}>{dateStr}</span>
      </span>
    );
  }

  const days = msLeft / (1000 * 60 * 60 * 24);
  const isUrgent  = days <= 1;
  const isWarning = days <= 7;
  const color = isUrgent ? 'var(--orange)' : isWarning ? 'var(--orange2)' : 'var(--muted)';

  return (
    <span style={{ color }}>
      {isWarning && <span style={{ marginRight: 4 }}>●</span>}
      {dateStr}
      {isWarning && (
        <span style={{ display: 'block', fontSize: 11, color: 'var(--dim)', marginTop: 1 }}>
          {isUrgent ? 'Today' : `${Math.ceil(days)}d left`}
        </span>
      )}
    </span>
  );
}

/** Post-create step: shows the shareable token URL with copy/preview actions. */
function SuccessStep({ token, onCopy, onPreview, onClose, copiedId }) {
  const url = BASE_URL + token;
  return (
    <>
      <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div aria-hidden="true" style={{ width: 32, height: 32, borderRadius: '50%', background: 'rgba(61,220,132,.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--green)', fontSize: 16, flexShrink: 0 }}>
            ✓
          </div>
          <div style={{ fontSize: 13, color: 'var(--muted)' }}>
            Dashboard created. Share this URL with the agency: no login required.
          </div>
        </div>
        <div style={{
          background: 'var(--surface2)', border: '1px solid var(--border)',
          borderRadius: 6, padding: '10px 14px',
          fontSize: 12, color: 'var(--muted)', wordBreak: 'break-all',
          fontFamily: 'monospace', lineHeight: 1.5,
        }}>
          {url}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn btn-primary btn-sm" onClick={onCopy}>
            {copiedId === '__new' ? '✓ Copied!' : 'Copy URL'}
          </button>
          <button className="btn btn-secondary btn-sm" onClick={onPreview}>
            Preview <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} />
          </button>
        </div>
        <div style={{ fontSize: 11, color: 'var(--dim)', lineHeight: 1.6 }}>
          You can copy this URL later from the dashboard list. Deactivate the link any time to immediately block access.
        </div>
      </div>
      <div className="modal-footer">
        <button className="btn btn-primary" onClick={onClose}>Done</button>
      </div>
    </>
  );
}
