/**
 * components/shared/SecurityPage.js: self-service TOTP + password management.
 *
 * Two cards: TOTP enrollment/removal (enroll -> scan QR -> verify 6-digit code)
 * and Change Password.
 *
 * @security AAL2-only surface. Supabase Auth "Require current password" must be
 *           OFF for the password update to work. @see CLAUDE.md (Auth)
 * @perf @zxcvbn-ts is dynamic-imported on first open of the password form, kept
 *       out of the eager bundle (loadZxcvbn / zxcvbnFnCache).
 */
import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { supabase } from '../../lib/supabase';
import { useConfirm } from './ConfirmDialog';
import { useStepUp } from './useStepUp';
import { humanizeError } from '../../utils/errors';
import Feedback from './Feedback';
import Loading from './Loading';
import SubmitButton from './SubmitButton';

export default function SecurityPage() {
  const askConfirm = useConfirm();
  const stepUp = useStepUp();
  const { mfaState, listMFAFactors, unenrollMFA, enrollMFA, confirmEnrollment } = useAuth();
  const [factors, setFactors]           = useState(null);
  const [factorsLoading, setFactorsLoading] = useState(true);
  const [pageError, setPageError]       = useState('');

  // Enrollment flow state
  const [enrollStep, setEnrollStep]     = useState(null); // null | 'loading' | 'qr' | 'verify'
  const [enrollData, setEnrollData]     = useState(null); // { factorId, qrCode, secret }
  const [showSecret, setShowSecret]     = useState(false);
  const [verifyCode, setVerifyCode]     = useState('');
  const [verifyError, setVerifyError]   = useState('');
  const [verifyLoading, setVerifyLoading] = useState(false);
  const enrollStarted = useRef(false);

  useEffect(() => {
    loadFactors();
  }, []);

  async function loadFactors() {
    setFactorsLoading(true);
    // A re-read is the only thing that can answer the last failure, so it clears it first.
    // Without this the banner outlives the condition it describes.
    setPageError('');
    const { factors: f, error: err } = await listMFAFactors();
    if (err) setPageError('Could not load security settings.');
    else setFactors(f ?? []);
    setFactorsLoading(false);
  }

  async function handleUnenroll(factorId) {
    if (!(await askConfirm({ title: 'Remove two-factor authentication?', body: 'Your account will be less secure. You can re-enable it later.', danger: true, confirmLabel: 'Remove 2FA' }))) return;
    /* Removing the factor is the takeover step: it is
     * what turns a borrowed session into permanent ownership. Asked AFTER the ordinary confirm
     * so somebody who opened this by accident is not made to fetch their phone first. */
    if (!(await stepUp({ title: 'Enter your authenticator code', body: 'Removing two-factor authentication needs the code from your authenticator app.', danger: true }))) return;
    const { error: err } = await unenrollMFA(factorId);
    if (err) setPageError('Could not remove 2FA. ' + (humanizeError(err).body || ''));
    else loadFactors();
  }

  async function startEnroll() {
    if (enrollStarted.current) return;
    enrollStarted.current = true;
    setEnrollStep('loading');
    setPageError('');
    const { factorId, qrCode, secret, error: err } = await enrollMFA();
    if (err) {
      setPageError('Could not start setup. Try again.');
      setEnrollStep(null);
      enrollStarted.current = false;
      return;
    }
    setEnrollData({ factorId, qrCode, secret });
    setEnrollStep('qr');
  }

  function cancelEnroll() {
    setEnrollStep(null);
    setEnrollData(null);
    setVerifyCode('');
    setVerifyError('');
    setShowSecret(false);
    enrollStarted.current = false;
  }

  async function handleVerify(e) {
    e.preventDefault();
    if (verifyCode.length !== 6) { setVerifyError('Enter the 6-digit code.'); return; }
    setVerifyLoading(true);
    setVerifyError('');
    const { error: err } = await confirmEnrollment(enrollData.factorId, verifyCode);
    if (err) {
      setVerifyError('Incorrect code. Make sure your phone time is correct and try again.');
      setVerifyCode('');
    } else {
      cancelEnroll();
      loadFactors();
    }
    setVerifyLoading(false);
  }

  const enrolled = factors && factors.length > 0;

  return (
    <div style={{ padding: '36px 40px', maxWidth: 600 }}>
      <div style={{ marginBottom: 32 }}>
        <h1 className="page-title">SECURITY</h1>
        <div className="text-muted text-sm" style={{ marginTop: 6 }}>
          Manage your password and two-factor authentication.
        </div>
      </div>

      <div className="card">
        <h2 className="card-title">Two-Factor Authentication</h2>

        {factorsLoading && <Loading />}

        {!factorsLoading && pageError && <Feedback value={pageError} style={{ marginBottom: 12 }} />}

        {/* Enrolled state */}
        {!factorsLoading && enrolled && (
          <>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
              <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--green)', flexShrink: 0 }} />
              <div>
                <span style={{ fontSize: 14, fontWeight: 600 }}>Enabled</span>
                <span className="text-muted text-sm" style={{ marginLeft: 8 }}>
                  Your account is protected with an authenticator app.
                </span>
              </div>
            </div>
            {factors.map(f => (
              <div key={f.id} style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                padding: '12px 16px', background: 'var(--surface2)', borderRadius: 8, marginBottom: 8,
              }}>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 600 }}>Authenticator App</div>
                  <div className="text-muted text-xs" style={{ marginTop: 3 }}>
                    Added {new Date(f.created_at).toLocaleDateString('en-US', {
                      month: 'short', day: 'numeric', year: 'numeric',
                    })}
                  </div>
                </div>
                <button className="btn btn-danger btn-sm" onClick={() => handleUnenroll(f.id)}>
                  Remove
                </button>
              </div>
            ))}
          </>
        )}

        {/* Not enrolled: idle state */}
        {!factorsLoading && factors && !enrolled && enrollStep === null && (
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16 }}>
              <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--orange2)', flexShrink: 0 }} />
              <span style={{ fontSize: 14, fontWeight: 600 }}>Not enabled</span>
            </div>
            {mfaState === 'needs_enrollment' && (
              <div style={{
                padding: '10px 14px',
                background: 'rgba(255,140,66,0.08)',
                border: '1px solid rgba(255,140,66,0.2)',
                borderRadius: 8,
                fontSize: 13,
                color: 'var(--orange2)',
                marginBottom: 16,
              }}>
                Set up two-factor authentication to protect your account.
              </div>
            )}
            <button className="btn btn-primary" onClick={startEnroll}>
              Set Up Authenticator App
            </button>
          </div>
        )}

        {/* Enrollment: loading */}
        {enrollStep === 'loading' && (
          <div className="text-muted">Generating setup code…</div>
        )}

        {/* Enrollment: QR code */}
        {enrollStep === 'qr' && enrollData && (
          <div>
            <p style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 16, lineHeight: 1.6 }}>
              Open your authenticator app (Google Authenticator, Authy, or 1Password), tap the{' '}
              <strong style={{ color: 'var(--white)' }}>+</strong> button, and scan this QR code.
            </p>
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 12 }}>
              <img
                src={enrollData.qrCode}
                alt="QR code for authenticator setup"
                style={{ width: 160, height: 160, borderRadius: 8, background: 'var(--paper)', padding: 8 }}
              />
            </div>
            <button
              type="button"
              className="login-footer-link"
              style={{ display: 'block', marginBottom: showSecret ? 8 : 16, textAlign: 'left' }}
              onClick={() => setShowSecret(s => !s)}
            >
              {showSecret ? 'Hide manual code' : "Can't scan? Enter the code manually instead"}
            </button>
            {showSecret && (
              <div style={{
                background: 'var(--surface3)', borderRadius: 6, padding: '10px 14px',
                fontFamily: 'monospace', fontSize: 12, letterSpacing: '0.1em',
                wordBreak: 'break-all', marginBottom: 16, color: 'var(--white)',
              }}>
                {enrollData.secret}
              </div>
            )}
            <div style={{ display: 'flex', gap: 8 }}>
              <button className="btn btn-primary" onClick={() => setEnrollStep('verify')}>
                I've scanned it →
              </button>
              <button className="btn btn-ghost" onClick={cancelEnroll}>Cancel</button>
            </div>
          </div>
        )}

        {/* Enrollment: verify */}
        {enrollStep === 'verify' && enrollData && (
          <div>
            <p style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 16, lineHeight: 1.6 }}>
              Enter the 6-digit code your app is showing now to confirm it's working.
            </p>
            {verifyError && <Feedback value={verifyError} style={{ marginBottom: 12 }} />}
            <form onSubmit={handleVerify} autoComplete="one-time-code">
              <div className="form-group">
                <label className="form-label" htmlFor="security-verify-code">Verification Code</label>
                <input
                  id="security-verify-code"
                  className="form-input"
                  type="text"
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={6}
                  value={verifyCode}
                  onChange={e => setVerifyCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  placeholder="000000"
                  autoFocus
                  autoComplete="one-time-code"
                  disabled={verifyLoading}
                  style={{ letterSpacing: '0.3em', fontSize: 18, textAlign: 'center', maxWidth: 160 }}
                />
              </div>
              <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
                <button
                  className="btn btn-primary"
                  type="submit"
                  disabled={verifyLoading || verifyCode.length !== 6}
                >
                  {verifyLoading ? 'Confirming…' : 'Confirm & Enable 2FA'}
                </button>
                <button
                  type="button"
                  className="btn btn-ghost"
                  onClick={() => { setEnrollStep('qr'); setVerifyCode(''); setVerifyError(''); }}
                >
                  ← Back
                </button>
              </div>
            </form>
          </div>
        )}
      </div>

      <ChangePasswordCard />
    </div>
  );
}

// Loaded once per session the first time the change-password form opens.
let zxcvbnFnCache = null;
async function loadZxcvbn() {
  if (zxcvbnFnCache) return zxcvbnFnCache;
  const [{ zxcvbn, zxcvbnOptions }, { adjacencyGraphs, dictionary }] = await Promise.all([
    import('@zxcvbn-ts/core'),
    import('@zxcvbn-ts/language-common'),
  ]);
  zxcvbnOptions.setOptions({ graphs: adjacencyGraphs, dictionary });
  zxcvbnFnCache = zxcvbn;
  return zxcvbn;
}

// Policy: 12+ chars, all 5 character classes, zxcvbn score >= 3. @see CLAUDE.md (Auth)
const PW_MIN_LENGTH = 12;  // minimum character count
const PW_MIN_ZXCVBN = 3;   // minimum zxcvbn score (0-4); 3 = "Good"

const STRENGTH_LABELS = ['Very weak', 'Weak', 'Fair', 'Good', 'Strong'];
const STRENGTH_COLORS = ['var(--red)', 'var(--red)', 'var(--orange2)', 'var(--orange)', 'var(--green)'];

const CHAR_RULES = [
  { label: `${PW_MIN_LENGTH}+ characters`, test: pw => pw.length >= PW_MIN_LENGTH },
  { label: 'Uppercase letter',             test: pw => /[A-Z]/.test(pw) },
  { label: 'Lowercase letter',             test: pw => /[a-z]/.test(pw) },
  { label: 'Number',                       test: pw => /\d/.test(pw) },
  { label: 'Special character',            test: pw => /[^A-Za-z0-9]/.test(pw) },
];

/**
 * The password-change card. Submit gates on all char rules + zxcvbn >= 3 (or
 * char rules alone if zxcvbn failed to load) + matching confirmation.
 */
function ChangePasswordCard() {
  const stepUp = useStepUp();
  const [open, setOpen]           = useState(false);
  const [newPw, setNewPw]         = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [saving, setSaving]       = useState(false);
  const [error, setError]         = useState('');
  const [success, setSuccess]     = useState(false);
  const [zxcvbnLoading, setZxcvbnLoading] = useState(false);
  const [zxcvbnFn, setZxcvbnFn]   = useState(null);
  const successTimer              = useRef(null);

  // Clear any pending success timer on unmount so we don't setSuccess
  // on an unmounted component (the navigation-away race).
  useEffect(() => () => clearTimeout(successTimer.current), []);

  async function handleOpen() {
    setSuccess(false);
    setOpen(true);
    if (!zxcvbnFnCache) setZxcvbnLoading(true);
    try {
      const fn = await loadZxcvbn();
      setZxcvbnFn(() => fn);
    } catch {
      // zxcvbn failed to load - strength scoring unavailable, char rules still enforce
    }
    setZxcvbnLoading(false);
  }

  function reset() {
    setNewPw('');
    setConfirmPw('');
    setError('');
  }

  function handleCancel() {
    setOpen(false);
    reset();
  }

  const zxResult      = zxcvbnFn && newPw ? zxcvbnFn(newPw) : null;
  const score         = zxResult ? zxResult.score : 0;          // 0-4
  const hint          = zxResult?.feedback?.warning || zxResult?.feedback?.suggestions?.[0] || '';
  const charsPassing  = CHAR_RULES.every(r => r.test(newPw));
  const mismatch      = confirmPw.length > 0 && newPw !== confirmPw;
  // zxcvbn must score ≥ 3 when loaded; if it failed to load fall back to char rules alone
  const strengthOk    = zxcvbnLoading ? false : (zxcvbnFn ? score >= PW_MIN_ZXCVBN : charsPassing);
  const canSubmit     = charsPassing && strengthOk && !mismatch && newPw === confirmPw && !saving;

  async function handleSubmit(e) {
    e.preventDefault();
    if (!canSubmit) return;
    /* The other half of takeover. Asked before anything
     * is sent, so a refused code costs the user nothing and changes nothing. Supabase's own
     * "require current password" stays OFF: the re-proof here is the authenticator code, which
     * is why this form still has two fields. @see docs/CODEBASE.md section 13 */
    if (!(await stepUp({ title: 'Enter your authenticator code', body: 'Changing your password needs the code from your authenticator app.' }))) return;
    setSaving(true);
    setError('');
    const { error: updateErr } = await supabase.auth.updateUser({ password: newPw });
    // Lowered only on the path that stays: the success path ends in a sign-out that tears this
    // form down, so handing the button back before it would re-arm a control nobody should be
    // able to press again. @see src/__tests__/savingBeforeAwait.test.js
    if (updateErr) { setSaving(false); setError(humanizeError(updateErr).body || 'Could not update password.'); return; }
    reset();
    setOpen(false);
    setSuccess(true);
    clearTimeout(successTimer.current);
    successTimer.current = setTimeout(() => setSuccess(false), 3000);
    // @security every session ends, this one included. Changing a password is what somebody
    //           does when they think their account is compromised, and until this it moved
    //           nobody out: the attacker's refresh token stayed valid against the new password.
    //           Same consequence the reset path in pages/LoginPage.js already has, and it runs
    //           only after a SUCCESSFUL update, so a rejected change does not sign anyone out
    //           of a password they still have.
    await supabase.auth.signOut();
  }

  return (
    <div className="card" style={{ marginTop: 16 }}>
      <h2 className="card-title">Password</h2>

      {!open && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div className="text-muted text-sm">
            {success
              ? <span style={{ color: 'var(--green)', fontWeight: 600 }}>✓ Password updated</span>
              : 'Update your account password.'}
          </div>
          <button className="btn btn-secondary btn-sm" onClick={handleOpen}>
            Change Password
          </button>
        </div>
      )}

      {open && (
        <form onSubmit={handleSubmit} autoComplete="new-password">
          {error && <Feedback value={error} style={{ marginBottom: 12 }} />}

          <div className="form-group">
            <label className="form-label" htmlFor="pw-new">New Password</label>
            <input
              id="pw-new"
              className="form-input"
              type="password"
              value={newPw}
              onChange={e => setNewPw(e.target.value)}
              maxLength={128}
              autoFocus
              autoComplete="new-password"
              placeholder={`${PW_MIN_LENGTH}+ characters`}
              disabled={saving}
            />

            {/* Strength bar: shown once the user starts typing and zxcvbn is loaded */}
            {newPw.length > 0 && !zxcvbnLoading && (
              <div style={{ marginTop: 8 }}>
                <div style={{ display: 'flex', gap: 4, marginBottom: 5 }}>
                  {[0, 1, 2, 3, 4].map(i => (
                    <div key={i} style={{
                      height: 3, flex: 1, borderRadius: 2,
                      background: score > i ? STRENGTH_COLORS[score] : 'var(--surface3)',
                      transition: 'background 0.2s',
                    }} />
                  ))}
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
                  <span style={{ fontSize: 11, color: STRENGTH_COLORS[score], fontWeight: 600 }}>
                    {STRENGTH_LABELS[score]}
                  </span>
                  {hint && score < PW_MIN_ZXCVBN && (
                    <span style={{ fontSize: 11, color: 'var(--muted)' }}>{hint}</span>
                  )}
                </div>
              </div>
            )}

            {zxcvbnLoading && newPw.length > 0 && (
              <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6 }}>Checking strength…</div>
            )}

            {/* Character class checklist: shown once typing starts */}
            {newPw.length > 0 && (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 16px', marginTop: 10 }}>
                {CHAR_RULES.map(r => {
                  const ok = r.test(newPw);
                  return (
                    <div key={r.label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                      <span style={{
                        fontSize: 10, fontWeight: 700, lineHeight: 1,
                        color: ok ? 'var(--green)' : 'var(--dim)',
                      }}>
                        {ok ? '✓' : '○'}
                      </span>
                      <span style={{ fontSize: 11, color: ok ? 'var(--white)' : 'var(--muted)' }}>
                        {r.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="pw-confirm">Confirm Password</label>
            <input
              id="pw-confirm"
              className="form-input"
              type="password"
              value={confirmPw}
              onChange={e => setConfirmPw(e.target.value)}
              maxLength={128}
              autoComplete="new-password"
              placeholder="Re-enter new password"
              disabled={saving}
              style={confirmPw.length > 0 ? {
                outline: mismatch ? '1px solid var(--red)' : '1px solid var(--green)',
              } : {}}
            />
            {mismatch && (
              <div style={{ fontSize: 11, color: 'var(--red)', marginTop: 4 }}>Passwords don't match</div>
            )}
          </div>

          <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
            <SubmitButton saving={saving} className="btn btn-primary" type="submit" disabled={!canSubmit}>Update Password</SubmitButton>
            <button type="button" className="btn btn-ghost" onClick={handleCancel} disabled={saving}>
              Cancel
            </button>
          </div>
        </form>
      )}
    </div>
  );
}
