/**
 * components/shared/PayoutForm.js. The single shared payout editor, used by PaymentsPage
 * (campaign payouts) and RewardsPage (reward payouts).
 *
 * The caller passes a `parent` config; `parent.kind` picks campaign_id vs reward_entry_id on
 * write and the upstream-payment label (agency vs platform) on the not-yet-received gate. Holds
 * the OOP reimbursement carve-out and the advance-payout gate, and loads
 * its own payout, splits, destinations and split JEs so a parent panel threads nothing through.
 *
 * Never mounted for an in-kind deal: no cash is paid on one, so PaymentsPage renders no payout
 * tab and `components/shared/InKindRecord.js` is the screen that explains it instead.
 *
 * @example
 *   <PayoutForm parent={{ kind, parentId, creatorId, creatorName, youReceived,
 *                         payoutAmountDefault, invoiceId, contractedAmount }}
 *               onUpdated={reloadParent} />
 * @gotcha do NOT re-create a per-page PayoutForm; add the variation to `parent`. invoiceId and
 *         contractedAmount are campaign-only.
 * @gotcha `cashMonth` ('YYYY-MM', the month the upstream cash landed) retires this form for a
 *         creator on WAGES that whole month, who is settled a month at a time on Financials ->
 *         Payroll. It retires nothing for a creator on 1099, nothing for a payout that already
 *         exists, and nothing for a month her classification CHANGES inside, which payroll
 *         refuses to settle and sends back here one invoice at a time.
 * @invariant fn_prevent_advance_payout (DB) blocks a payout before the upstream invoice is
 *            received; this form mirrors it with a hard gate.
 * @see docs/MONEY.md Pattern E (payout), Pattern P (OOP reimbursement), Pattern F (split clear)
 */
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { useSplitForms } from '../../hooks/useSplitForms';
import { useConfirm } from './ConfirmDialog';
import { fmtMoney, fmtMonth, todayYMD, round2 } from '../../utils/format';
import { fetchCompBases, compBasisForMonth } from '../../utils/compBasis';
import { humanizeError } from '../../utils/errors';
import { clampSplitAmount, fetchExpenseOptions } from '../../utils/expenseCapacity';
import { fetchCreatorOutstanding, findOopDestination, buildOopSplitRow, pickPrimaryRealDestination, fetchCreatorRechargeOwed, buildRechargeSplitRow } from '../../utils/oopPayments';
import { PAYOUT_SPLIT_DESTINATION_EMBED } from '../../utils/queries';
import { computeSplitAmounts, buildSavePayoutArgs } from '../../utils/payoutPayload';
import SplitExpenseCapacity from './SplitExpenseCapacity';
import { usePayoutJournalEntries, LockedField, PostedBadge, PostedEntries, fetchJournalEntriesWithLines } from './InvoiceLock';
import ReverseEntryModal from './ReverseEntryModal';
import LockIcon from './LockIcon';
import Feedback from './Feedback';
import ReadError from './ReadError';
import { DB_DATE_MAX, DB_DATE_MIN } from '../../utils/dbLimits';
import Field from './Field';
import Loading from './Loading';
import { useToast } from './Toast';
import SubmitButton from './SubmitButton';
import MoneyInput from './MoneyInput';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';

/**
 * @param {object} props
 * @param {object} props.parent - {kind:'campaign'|'reward', parentId, creatorId, creatorName,
 *        youReceived, payoutAmountDefault, invoiceId?, contractedAmount?}
 * @param {function} props.onUpdated - called after a successful save / reverse so the parent re-fetches
 */
export default function PayoutForm({ parent, onUpdated }) {
  const toast = useToast();
  const today = todayYMD();
  const askConfirm = useConfirm();
  const { options: statusOptions, expenseAccounts } = useStatusOptions();
  const payoutOptions      = statusOptions.payout || [];
  const splitOptions       = statusOptions.split || [];
  const expenseCategories  = (expenseAccounts || []).filter((a) => a.is_active !== false);

  // ── Owned data ───────────────────────────────────────────────────────────
  const [payout, setPayout]               = useState(null);
  const [splits, setSplits]               = useState([]);
  const [destinations, setDestinations]   = useState([]);
  const [splitJes, setSplitJes]           = useState({});
  const [expenses, setExpenses]           = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state, twice, because the two reads feed different things. A refused
  // creator_payouts read left `payout` null, which is exactly what "no payout yet" looks
  // like: the posted badge disappeared, Payout Date unlocked on a payout whose Pattern E
  // entry is posted, the splits reset to a fresh 50/50, and Save then took the insert
  // branch. `creator_payouts_invoice_id_key` stops that only where `invoice_id` is set, and
  // NULLs do not collide, so a reward payout gets a second row. That one blocks the form.
  const [loadError, setLoadError]         = useState(null);
  // The destinations only fill the split pickers, so this one reports beside them rather
  // than blocking: an empty picker claims "No destinations configured for this creator",
  // which sends an admin to set up destinations that are already there.
  const [destError, setDestError]         = useState(null);
  const [compBases, setCompBases]         = useState(null);
  // Third one, same rule: the expense list only fills the split-row picker, so an empty one
  // claims no expense has an open balance and quietly removes the way a shared cost is
  // recovered from this payout.
  const [expensesError, setExpensesError] = useState(null);

  const parentKey = parent.kind === 'campaign' ? 'campaign_id' : 'reward_entry_id';

  const loadAll = useCallback(async () => {
    begin();
    setLoadError(null);
    setDestError(null);
    const [payRes, destRes, compRes] = await Promise.all([
      supabase
        .from('creator_payouts')
        .select(`*, payout_splits(*, ${PAYOUT_SPLIT_DESTINATION_EMBED}(*), expense:expenses(id, name, type, frequency, amount))`)
        .eq(parentKey, parent.parentId)
        .maybeSingle(),
      supabase
        .from('payment_destinations').select('*')
        .eq('profile_id', parent.creatorId)
        .eq('is_active', true)
        .order('sort_order'),
      // Whether this creator is on wages in the month the cash landed. Refused, the form blocks
      // rather than opening: it is the only thing standing between a wage month and a second
      // payout of cash a paycheck already settled. @see utils/compBasis.js
      fetchCompBases(supabase),
    ]);
    if (payRes.error || compRes.error) {
      setLoadError(payRes.error || compRes.error);
      setPayout(null);
      setSplits([]);
      setDestinations([]);
      end();
      return;
    }
    if (destRes.error) setDestError(destRes.error);
    setPayout(payRes.data);
    const currentSplits = payRes.data?.payout_splits || [];
    setSplits(currentSplits);
    setDestinations(destRes.data || []);
    setCompBases(compRes.data);
    end();
    const splIds = currentSplits.map((s) => s.id).filter(Boolean);
    if (splIds.length === 0) { setSplitJes({}); return; }
    // The split JEs decide which split rows are sealed. An empty map is "nothing cleared",
    // which is the same shape a refused ledger read leaves behind, so this blocks the form
    // rather than degrading to an editable one.
    try {
      const result = await fetchJournalEntriesWithLines('split', splIds);
      const map = {};
      for (const r of result) map[r.entry.source_id] = r;
      setSplitJes(map);
    } catch (e) {
      setSplitJes({});
      setLoadError(e);
    }
  }, [parentKey, parent.parentId, parent.creatorId, begin, end]);

  useEffect(() => { loadAll(); }, [loadAll]);
  const loadExpenses = useCallback(() => {
    setExpensesError(null);
    fetchExpenseOptions({ excludePayoutId: payout?.id })
      .then(setExpenses, (e) => { setExpenses([]); setExpensesError(e); });
  }, [payout?.id]);
  useEffect(() => { loadExpenses(); }, [loadExpenses]);

  // ── Payout-record form ────────────────────────────────────────────────────
  const [form, setForm] = useState({ payout_amount: '', payout_status_id: '', payout_date: '', payout_notes: '' });
  useEffect(() => {
    if (loading) return;
    setForm({
      payout_amount:    payout?.payout_amount ?? parent.payoutAmountDefault ?? '',
      payout_status_id: payout?.payout_status_id || payoutOptions.find(o => o.value === 'Pending')?.id || '',
      payout_date:      payout?.payout_date || '',
      payout_notes:     payout?.payout_notes || '',
    });
  }, [loading]);

  // ── Pattern E JE lock for the parent payout row ───────────────────────────
  const { payoutJe, payoutJes, error: payoutJeError, refetch: refetchPayoutJes } = usePayoutJournalEntries(payout?.id);
  const [reverseFor, setReverseFor] = useState(null);

  // ── Default splits (when no existing payout yet) ──────────────────────────
  const defaultSplits = () => {
    const pendingId = splitOptions.find(o => o.value === 'Pending')?.id || '';
    const base = { split_type: 'creator', expense_id: '', expense_period: '', split_status_id: pendingId, sent_date: '', cleared_date: '', reference: '', notes: '' };
    if (destinations.length >= 2) return [
      { ...base, destination_id: destinations[0].id, percentage: '50' },
      { ...base, destination_id: destinations[1].id, percentage: '50' },
    ];
    if (destinations.length === 1) return [{ ...base, destination_id: destinations[0].id, percentage: '100' }];
    return [{ ...base, destination_id: '', percentage: '100' }];
  };

  const { splitForms, setSplitForms, setSF, totalPct, onPctChange, onAmtChange } = useSplitForms([]);
  useEffect(() => {
    if (loading) return;
    setSplitForms(splits.length > 0
      ? splits.map(s => ({
          id:             s.id,
          split_type:     s.recharge_allocation_id ? 'recharge' : (s.expense_id ? 'expense' : 'creator'),
          destination_id: s.destination_id || '',
          reimbursement_destination_id: s.reimbursement_destination_id || '',
          expense_id:     s.expense_id || '',
          expense_period: s.expense_period ? s.expense_period.substring(0, 7) : '',
          recharge_allocation_id: s.recharge_allocation_id || '',
          percentage:     String(s.percentage ?? ''),
          amount_override: s.amount != null ? String(s.amount) : '',
          split_status_id: s.split_status_id || splitOptions.find(o => o.value === 'Pending')?.id || '',
          sent_date:      s.sent_date || '',
          cleared_date:   s.cleared_date || '',
          reference:      s.reference || '',
          notes:          s.notes || '',
        }))
      : defaultSplits()
    );
  }, [loading]);

  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [splitMaxByRow, setSplitMaxByRow] = useState({});
  const [clampedRow, setClampedRow] = useState(null);
  const onAmtChangeClamped = useCallback((i, val, payoutAmt2) => {
    const sf = splitForms[i];
    if (sf?.split_type === 'expense') {
      const max = splitMaxByRow[i];
      if (max != null) {
        const { value, clamped } = clampSplitAmount(val, max);
        if (clamped) {
          setClampedRow(i);
          setTimeout(() => setClampedRow(r => (r === i ? null : r)), 450);
        }
        onAmtChange(i, value, payoutAmt2);
        return;
      }
    }
    onAmtChange(i, val, payoutAmt2);
  }, [splitForms, splitMaxByRow, onAmtChange]);

  const payoutAmt = parseFloat(form.payout_amount) || 0;

  // The same function save() uses, at render, so the header and the refusal cannot disagree.
  // `totalPct` cannot see this: the last row IS defined as 100 minus the others, so the sum is
  // 100 by construction and stayed green beside a row reading -50.0000%.
  const splitAmounts = useMemo(() => computeSplitAmounts(splitForms, payoutAmt), [splitForms, payoutAmt]);
  const negativeSplit = splitAmounts.findIndex((a) => a !== null && a < -0.005);

  // The LLC is a pass-through: what the agency paid is what the creator is due,
  // so a payout that differs from the cash received is almost always a typo.
  // Three went in unnoticed (KYM-2026-0032 short by $2.10, two more by $0.10),
  // and splits seal on clearing, so nothing can be corrected in place after.
  // A hint, not a block: a genuine part-payment is possible.
  const receivedMismatch = (() => {
    const received = parseFloat(parent.payoutAmountDefault);
    if (!Number.isFinite(received) || !form.payout_amount) return null;
    const diff = Math.round((received - payoutAmt) * 100) / 100;
    return diff === 0 ? null : diff;
  })();

  // ── Carve-out prefill on a fresh payout (Patterns P + R) ─────────────────
  /**
   * Splice the carve-out splits a fresh payout owes, then RESCALE the real
   * destination rows to share whatever is left, so the column always totals the
   * payout and nothing ever goes negative. Two carve types:
   *   - OOP reimbursement (Pattern P): the LLC repays what the creator fronted.
   *     Rides a real account; counts as cash out.
   *   - Recharge (Pattern R): the creator's share of a company-paid expense.
   *     Moves NO cash; the creator simply foregoes that slice.
   * Carves are fixed dollar amounts taken first (OOP, then whole recharge
   * allocations that fit the remainder); the real destinations split
   * `payout - carves` by their original ratio. A recharge allocation that does
   * not fit stays owed for the next payout (never partially settled).
   * @gotcha real rows go LAST so the save's and useSplitForms' "last row absorbs
   *         the rounding" plug always lands on an editable destination, never on
   *         a locked carve row. @see docs/MONEY.md Patterns P, R
   */
  const [oopOutstanding, setOopOutstanding] = useState(0);
  const [oopLoaded, setOopLoaded] = useState(false);
  const [oopUnlockedRows, setOopUnlockedRows] = useState(() => new Set());
  const [rechargeOwed, setRechargeOwed] = useState({ total: 0, allocations: [] });
  const [rechargeLoaded, setRechargeLoaded] = useState(false);
  const [carveErr, setCarveErr] = useState(null);
  const [carvePrefilled, setCarvePrefilled] = useState(false);

  useEffect(() => {
    if (payout || !parent.creatorId) return;
    fetchCreatorOutstanding(parent.creatorId)
      .then((v) => { setOopOutstanding(v); setOopLoaded(true); })
      // Same treatment as the recharge read below, and for the same reason: a
      // refused read and a creator who is square both come back as 0, and the
      // difference is a reimbursement that is silently never carved.
      .catch((e) => { setCarveErr(humanizeError(e)); setOopLoaded(false); });
  }, [payout, parent.creatorId]);
  useEffect(() => {
    if (payout || !parent.creatorId) return;
    fetchCreatorRechargeOwed(parent.creatorId)
      .then((v) => { setRechargeOwed(v); setRechargeLoaded(true); })
      // The carve-out is a convenience, not the payout: on failure leave it
      // un-prefilled and say so, rather than blocking a payout that can be
      // entered by hand.
      .catch((e) => { setCarveErr(humanizeError(e)); setRechargeLoaded(false); });
  }, [payout, parent.creatorId]);

  useEffect(() => {
    if (carvePrefilled || payout || !payoutAmt || destinations.length === 0) return;
    if (!oopLoaded || !rechargeLoaded) return;

    const oopDest = oopOutstanding > 0 ? findOopDestination(destinations, parent.creatorId) : null;
    const hasOop = !!oopDest;
    if (!hasOop && rechargeOwed.total <= 0) { setCarvePrefilled(true); return; }
    const pendingId = splitOptions.find((o) => o.value === 'Pending')?.id || '';

    setSplitForms((sf) => {
      // On a fresh payout sf is the default real-destination rows. Be defensive:
      // keep only real rows (no recharge, not the OOP bucket).
      const realRows = sf.filter((s) =>
        s.split_type !== 'recharge' && !s.recharge_allocation_id &&
        destinations.find((d) => d.id === s.destination_id)?.oop_creator_id !== parent.creatorId
      );

      const carves = [];
      let budget = payoutAmt;

      // 1) OOP repayment first (capped at the payout).
      if (hasOop) {
        carves.push(buildOopSplitRow({
          destinationId: oopDest.id,
          reimbursementDestinationId: pickPrimaryRealDestination(destinations, parent.creatorId)?.id,
          outstanding: oopOutstanding,
          payoutAmt,
          pendingStatusId: pendingId,
        }));
        budget = round2(budget - Math.min(oopOutstanding, payoutAmt));
      }

      // 2) Whole recharge allocations that fit the remaining budget. Any that
      //    does not fit stays owed (it never appears, so it is not settled).
      for (const a of rechargeOwed.allocations) {
        const amt = round2(parseFloat(a.amount) || 0);
        if (amt <= 0 || amt > budget + 0.005) continue;
        carves.push(buildRechargeSplitRow(a, payoutAmt, pendingId));
        budget = round2(budget - amt);
      }

      const carveSum = round2(carves.reduce((s, r) => s + (parseFloat(r.amount_override) || 0), 0));
      const realBudget = round2(payoutAmt - carveSum);

      // 3) Rescale real rows to share realBudget by their original ratio; last
      //    real row absorbs the rounding, drop any that round to $0.
      let rescaledReal = [];
      if (realBudget >= 0.01 && realRows.length > 0) {
        const ratioTotal = realRows.reduce((s, r) => s + (parseFloat(r.percentage) || 0), 0) || realRows.length;
        let running = 0;
        rescaledReal = realRows.map((r, i) => {
          let amt;
          if (i < realRows.length - 1) {
            amt = round2(realBudget * ((parseFloat(r.percentage) || 0) / ratioTotal));
            running = round2(running + amt);
          } else {
            amt = round2(realBudget - running);
          }
          return { ...r, amount_override: amt.toFixed(2), percentage: ((amt / payoutAmt) * 100).toFixed(4) };
        }).filter((r) => parseFloat(r.amount_override) >= 0.005);
      }

      // Carve % against the payout so the whole column sums to 100. Real rows
      // last, so the rounding plug always lands on an editable destination.
      const finalCarves = carves.map((r) => ({
        ...r,
        percentage: (((parseFloat(r.amount_override) || 0) / payoutAmt) * 100).toFixed(4),
      }));
      return [...finalCarves, ...rescaledReal];
    });
    setCarvePrefilled(true);
  }, [carvePrefilled, payout, payoutAmt, destinations, oopLoaded, rechargeLoaded, oopOutstanding, rechargeOwed, parent.creatorId, splitOptions]);

  // ── Save ─────────────────────────────────────────────────────────────────
  /**
   * Write the payout and every split in ONE transaction, through `save_payout_with_splits`.
   *
   * Upserting the payout, then each split, then create_split_cleared_entry per cleared split
   * is one committed transaction each, and an error branch that returns leaves a payout
   * carrying only some of its splits with trg_fn_splits_ledger already reconciled to that
   * partial set.
   *
   * @invariant split percentages must total 100% before save. Checked here so the message can
   *            name the figure, and again in the RPC, because a control that only exists in
   *            the browser is not a control.
   * @gotcha the RPC still re-calls create_split_cleared_entry per cleared split: the
   *         reverse-then-edit flow can leave cleared_date unchanged so the trigger would not
   *         re-fire. Its NOT EXISTS guard makes it a no-op when a live JE exists.
   */
  async function save() {
    // Payout Date is required, and refused first because it sits above the splits and the
    // cascade reads top-down. This date IS the journal entry's date:
    // reconcile_payout_journal_entry raises on a blank one, and once that entry is live
    // prevent_payout_trigger_field_mutation seals the column, so a blank that gets past here
    // can only be corrected by reversing the entry. Not gated on payoutJe: the field is
    // disabled once posted, and a posted payout cannot hold a blank date.
    if (!form.payout_date) { setError('Enter the date this payout was made.'); return; }
    if (Math.abs(totalPct - 100) > 0.01) { setError(`Splits must total 100%. Currently ${totalPct.toFixed(1)}%`); return; }
    if (splitForms.some(s => s.split_type === 'creator' && !s.destination_id)) { setError('All creator splits need a destination.'); return; }
    if (splitForms.some(s => s.split_type === 'expense' && !s.expense_id)) { setError('All expense splits need an expense selected.'); return; }
    // @invariant a split cannot clear before it was sent. `chk_payout_splits_dates` bounds each
    //            column on its own and says nothing about their order, so this and the Cleared
    //            Date field's own `min` are the only two guards. ISO YYYY-MM-DD sorts
    //            lexically. Found sweeping the ordered date pairs.
    if (splitForms.some(s => s.sent_date && s.cleared_date && s.cleared_date < s.sent_date)) {
      setError('A split cannot be cleared before it was sent. Check the sent and cleared dates.');
      return;
    }
    setSaving(true); setError('');

    const amounts = computeSplitAmounts(splitForms, payoutAmt);
    // Safety net: a split amount can never be negative. If the splits over-allocate
    // (e.g. carve-outs exceed the payout), block the save with a clear message
    // instead of writing an impossible negative payout.
    if (amounts.some(a => a !== null && a < -0.005)) {
      setError('Splits over-allocate the payout (a split came out negative). Lower a destination amount or raise the payout.');
      setSaving(false);
      return;
    }

    const args = buildSavePayoutArgs({ parent, form, payoutAmt, splitForms, payoutId: payout?.id || null });
    const { error: saveErr } = await supabase.rpc('save_payout_with_splits', {
      p_payout: args.payout,
      p_splits: args.splits,
    });
    if (saveErr) { setError(humanizeError(saveErr).body || 'Could not save the payout.'); setSaving(false); return; }

    // After the reload, not before it. `payout` is still null until loadAll returns, so a
    // second Save in that window sends payoutId: null again and save_payout_with_splits
    // takes its insert branch twice. Today the reload blanks the form so the button is not
    // reachable; that is loadAll's `loading` flag doing it, and P178 is about to take it away.
    await loadAll();
    setSaving(false);
    toast.success('Payout saved');
    onUpdated();
  }

  // ── Render ───────────────────────────────────────────────────────────────
  if (loading) return <Loading />;
  // Before the form, never beside it: a payout the read could not confirm is absent may not
  // be offered a Save that inserts one.
  if (loadError) return <ReadError error={loadError} onRetry={loadAll} />;
  // Same rule one level down: payoutJe is null both when nothing is posted and when the probe
  // was refused, and it is what disables Payout Date and hides the posted badge.
  if (payoutJeError) return <ReadError error={payoutJeError} onRetry={refetchPayoutJes} />;

  // A creator on wages is settled a MONTH at a time, so a per-invoice payout for one of her
  // invoices would pay that cash twice: once here and once inside the monthly paycheck, which
  // settles everything the month collected and names no invoice for the database to notice.
  // Only offered while no payout EXISTS: January to July 2026 were paid this way before the
  // switch and those records stay editable, which is D7 in the plan. The whole form stays for
  // anyone on 1099, and Kym comes back to it at 18.
  if (!payout && parent.cashMonth
      && compBasisForMonth(compBases, parent.creatorId, parent.cashMonth) === 'w2') {
    return (
      <div>
        <Feedback value={{
          tone: 'info',
          title: `${fmtMonth(parent.cashMonth)} is settled on payroll`,
          body: `${parent.creatorName || 'This creator'} is a W-2 employee, so every payment that `
              + 'landed this month is settled together in one paycheck rather than one payout per '
              + 'invoice. Nothing to record here.',
        }} />
        <button type="button" className="btn btn-ghost btn-sm" style={{ marginTop: 12 }} onClick={() => {
          window.dispatchEvent(new window.CustomEvent('nys:open-ledger', {
            detail: { tab: 'payroll', month: parent.cashMonth },
          }));
        }}>
          Open {fmtMonth(parent.cashMonth)} payroll
        </button>
      </div>
    );
  }

  // Strict gate: no payout work until upstream invoice is received.
  // The DB trigger fn_prevent_advance_payout enforces the same rule.
  if (!parent.youReceived) {
    const upstream = parent.kind === 'campaign' ? 'agency' : 'platform';
    const invoiceKind = parent.kind === 'campaign' ? 'agency' : 'reward';
    return (
      <Feedback value={{
        tone: 'warn',
        title: `Waiting on ${upstream} payment`,
        body: `Payout records unlock once the ${invoiceKind} invoice is marked received on the Invoice tab. We never pay a creator before the LLC has the cash.`,
      }} />
    );
  }

  return (
    <div>
      <h3 className="detail-section-title">PAYOUT TO {(parent.creatorName || 'CREATOR').toUpperCase()}<PostedBadge visible={!!payoutJe} /><Refreshing on={refreshing} /></h3>
      <div className="form-row">
        <Field label="Payout Amount ($)">{(id) => (<>
          <MoneyInput id={id} value={form.payout_amount} onChange={e => setForm(f => ({ ...f, payout_amount: e.target.value }))} />
          {receivedMismatch !== null && (
            <div className="form-hint form-hint-warn">
              {fmtMoney(Math.abs(receivedMismatch))} {receivedMismatch > 0 ? 'less' : 'more'} than
              the {fmtMoney(parseFloat(parent.payoutAmountDefault))} that came in. This is a
              pass-through, so it normally matches exactly.
            </div>
          )}
        </>)}</Field>
        <Field label="Payout Status">{(id) => (<>
          <select id={id} className="form-select" value={form.payout_status_id} onChange={e => setForm(f => ({ ...f, payout_status_id: e.target.value }))}>
            {payoutOptions.map(o => <option key={o.id} value={o.id}>{o.label}</option>)}
          </select>
        </>)}</Field>
      </div>
      <div className="form-row">
        <Field label="Payout Date">{(id) => (<>
          <LockedField je={payoutJe} onReverse={setReverseFor} tooltip="Locked. Reverse the payout entry to edit the date.">
            {/* Capped at today, not at DB_DATE_MAX: a payout is something that has already
                happened, and this date becomes a journal entry's date, so a typo dates the
                books years out. Same rule the Cleared Date below already follows. */}
            <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={today} value={form.payout_date} disabled={!!payoutJe} onChange={e => setForm(f => ({ ...f, payout_date: e.target.value }))} style={payoutJe ? { paddingRight: 38 } : undefined} />
          </LockedField>
        </>)}</Field>
      </div>
      <Field label="Notes">{(id) => (<>
        <input id={id} className="form-input" value={form.payout_notes} maxLength={500} onChange={e => setForm(f => ({ ...f, payout_notes: e.target.value }))} placeholder="e.g. Deducted $12 processing fee" />
      </>)}</Field>
      <div className="divider" />
      <div className="flex items-center justify-between mb-12">
        <div>
          <h3 className="detail-section-title" style={{ marginBottom: 2 }}>DESTINATION SPLITS</h3>
          <div style={{ fontSize: 11, color: negativeSplit >= 0 ? 'var(--red)' : Math.abs(totalPct - 100) < 0.01 ? 'var(--green)' : 'var(--orange)' }}>
            {totalPct.toFixed(1)}% allocated of {fmtMoney(payoutAmt)}
          </div>
          {/* Colour is never the only signal, and the balancing row carries no label, so the
              sentence has to name which row absorbed the overshoot. */}
          {negativeSplit >= 0 && (
            <div role="alert" style={{ fontSize: 11, color: 'var(--red)', marginTop: 3, lineHeight: 1.4 }}>
              Split {negativeSplit + 1} comes out at -{fmtMoney(Math.abs(splitAmounts[negativeSplit]))}. Lower another split or raise the payout.
            </div>
          )}
        </div>
        <button className="btn btn-secondary btn-sm" onClick={() => setSplitForms(sf => [...sf, { split_type: 'creator', destination_id: '', expense_id: '', expense_period: '', percentage: '', amount_override: '', split_status_id: splitOptions.find(o => o.value === 'Pending')?.id || '', sent_date: '', cleared_date: '', reference: '', notes: '' }])}>+ Add Split</button>
      </div>
      {/* Reported HERE and not at the top: the shared-cost carve-out is a
          prefill, so its failure costs an admin one manual split rather than
          the payout. Scoped to the surface it feeds. */}
      {carveErr && <div style={{ marginBottom: 12 }}><Feedback value={carveErr} /></div>}
      {expensesError && (
        <div style={{ marginBottom: 12 }}><ReadError error={expensesError} onRetry={loadExpenses} /></div>
      )}
      {destError ? (
        <div style={{ marginBottom: 12 }}><ReadError error={destError} onRetry={loadAll} /></div>
      ) : destinations.length === 0 && (
        <div style={{ padding: '10px 14px', borderRadius: 6, marginBottom: 12, fontSize: 12, background: 'rgba(255,82,82,0.08)', border: '1px solid rgba(255,82,82,0.2)', color: 'var(--red)' }}>
          No destinations configured for this creator. Go to Setup → Payment Destinations.
        </div>
      )}
      {oopOutstanding > 0 && !splitForms.some((s) => {
        const d = destinations.find((x) => x.id === s.destination_id);
        return d?.oop_creator_id === parent.creatorId;
      }) && (
        <div style={{ padding: '10px 14px', borderRadius: 6, marginBottom: 12, fontSize: 12, background: 'color-mix(in oklab, var(--orange) 8%, transparent)', border: '1px solid color-mix(in oklab, var(--orange) 25%, transparent)', color: 'var(--orange)' }}>
          Outstanding out-of-pocket of {fmtMoney(oopOutstanding)} will carry to the next payout.
        </div>
      )}
      {rechargeOwed.total > 0 && !splitForms.some((s) => s.split_type === 'recharge') && (
        <div style={{ padding: '10px 14px', borderRadius: 6, marginBottom: 12, fontSize: 12, background: 'color-mix(in oklab, var(--orange) 8%, transparent)', border: '1px solid color-mix(in oklab, var(--orange) 25%, transparent)', color: 'var(--orange)' }}>
          {fmtMoney(rechargeOwed.total)} of company-paid expenses will be recovered from this payout. Enter the payout amount to apply it.
        </div>
      )}
      {splitForms.map((sf, i) => {
        const je = sf.id ? splitJes[sf.id] : null;
        const locked = !!je;
        const destObj = destinations.find(d => d.id === sf.destination_id);
        const isDeferred = !!destObj?.is_deferred;
        const isOopRow = !!destObj && destObj.oop_creator_id === parent.creatorId;
        const isRechargeRow = sf.split_type === 'recharge' || !!sf.recharge_allocation_id;
        const oopUnlocked = oopUnlockedRows.has(i);
        const oopLockActive = isOopRow && !oopUnlocked && !locked;
        // Recharge rows are auto-prefilled and carved; lock pct/amount by default,
        // same admin-override affordance as the OOP reimbursement row.
        const rechargeLockActive = isRechargeRow && !oopUnlocked && !locked;
        const autoLockActive = oopLockActive || rechargeLockActive;
        return (
        <div key={i} className="deliverable-card" style={{ marginBottom: 10 }}>
          <div className="deliverable-card-header">
            <span style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>
              Split {i + 1}
              {isOopRow ? <span style={{ marginLeft: 6, fontFamily: 'var(--font-display)', fontSize: 9, color: 'var(--orange)', letterSpacing: '1.5px' }}>· REIMBURSEMENT</span> : null}
              {isRechargeRow ? <span style={{ marginLeft: 6, fontFamily: 'var(--font-display)', fontSize: 9, color: 'var(--orange)', letterSpacing: '1.5px' }}>· RECHARGE</span> : null}
              {locked ? <span style={{ marginLeft: 6, fontSize: 10, color: 'var(--orange)', display: 'inline-flex', alignItems: 'center', gap: 4 }}><LockIcon size={11} /> Posted</span> : null}
            </span>
            {splitForms.length > 1 && !locked && (
              <button className="btn btn-ghost btn-sm" onClick={async () => {
                // The destination is what the reader recognises; "Split 3" is a position in a
                // list they are about to renumber.
                if (sf.id) { if (!(await askConfirm({ title: `Remove the split to ${destObj?.name || `split ${i + 1}`}?`, body: 'This cannot be undone.', danger: true }))) return; await supabase.from('payout_splits').delete().eq('id', sf.id); }
                setSplitForms(sf2 => sf2.filter((_, idx) => idx !== i));
              }}>Remove</button>
            )}
          </div>
          {locked ? (
            <div style={{ padding: '8px 12px', borderRadius: 4, marginBottom: 10, fontSize: 11, background: 'rgba(255,92,0,0.06)', border: '1px solid rgba(255,92,0,0.2)', color: 'var(--orange)', display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8 }}>
              <span style={{ flex: 1 }}>
                Posted to ledger. Reverse the entry to edit amount, destination, or cleared date.
                <br />
                <span style={{ color: 'var(--muted)' }}>Sent date and reference can be edited inline without reversing.</span>
              </span>
              <button
                onClick={() => setReverseFor(je)}
                style={{ background: 'transparent', border: 0, color: 'var(--orange)', cursor: 'pointer', textDecoration: 'underline', fontSize: 11, fontFamily: 'inherit', padding: 0, whiteSpace: 'nowrap' }}
              >Reverse posted entry…</button>
            </div>
          ) : null}
          {/* Split type toggle (hidden for auto-prefilled recharge rows) */}
          {!isRechargeRow && (
          <div style={{ display: 'flex', gap: 0, marginBottom: 10, background: 'var(--surface)', borderRadius: 4, padding: 2, border: '1px solid var(--border2)', width: 'fit-content', opacity: locked ? 0.5 : 1, pointerEvents: locked ? 'none' : 'auto' }}>
            {[{ v: 'creator', label: 'CREATOR' }, { v: 'expense', label: 'EXPENSE' }].map(({ v, label }) => (
              <button key={v} onClick={() => setSF(i, 'split_type', v)} disabled={locked} style={{
                padding: '4px 12px', border: 'none', borderRadius: 3, cursor: locked ? 'not-allowed' : 'pointer',
                fontSize: 9, fontFamily: 'var(--font-body)', fontWeight: 700, letterSpacing: '1px', textTransform: 'uppercase',
                background: sf.split_type === v ? 'var(--surface2)' : 'transparent',
                color: sf.split_type === v ? 'var(--white)' : 'var(--muted)',
                transition: 'all 0.15s',
              }}>{label}</button>
            ))}
          </div>
          )}

          <div className="form-row" style={{ marginBottom: 8 }}>
            <div className="form-group" style={{ marginBottom: 0 }}>
              {isRechargeRow ? (
                <>
                  <div className="form-label">Company-paid expense</div>
                  <div style={{ padding: '9px 12px', borderRadius: 4, fontSize: 13, background: 'var(--surface)', border: '1px solid var(--border2)', color: 'var(--white)' }}>
                    {sf.notes ? sf.notes.replace(/^Recharge:\s*/, '') : 'Company-paid expense'}
                  </div>
                  <div style={{ marginTop: 6, fontSize: 11, color: 'var(--muted)', lineHeight: 1.5 }}>
                    Comes out of this payout (not on top). The company already paid this from checking; {parent.creatorName || 'the creator'} covers this share, so no cash is sent for this line.
                  </div>
                  {!locked ? (
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      onClick={() => setOopUnlockedRows((prev) => {
                        const next = new Set(prev);
                        if (next.has(i)) next.delete(i); else next.add(i);
                        return next;
                      })}
                      style={{ marginTop: 4, fontSize: 10, padding: '2px 6px', color: 'var(--muted)' }}
                    >· {oopUnlocked ? 'Re-lock' : 'Admin override'}</button>
                  ) : null}
                </>
              ) : sf.split_type === 'expense' ? (
                <>
                  <div className="form-label">Expense</div>
                  <select aria-label="Expense"
                    className="form-select"
                    value={sf.expense_id ? `${sf.expense_id}|${sf.expense_period || ''}` : ''}
                    disabled={locked}
                    onChange={e => {
                      const [eid, pk] = e.target.value.split('|');
                      setSplitForms(sf2 => sf2.map((s, idx) => idx === i ? { ...s, expense_id: eid || '', expense_period: pk || '' } : s));
                    }}
                  >
                    <option value="">Select expense with open balance…</option>
                    {expenses.map(opt => {
                      const key = `${opt.expense_id}|${opt.period_key || ''}`;
                      const cat = expenseCategories.find(c => c.id === opt.category_id)?.name || '';
                      const periodSuffix = opt.period_label ? ` · ${opt.period_label}` : '';
                      const balanceSuffix = ` · ${fmtMoney(opt.remaining)} of ${fmtMoney(opt.cap)} left`;
                      return (
                        <option key={key} value={key}>
                          {opt.expense_name} · {cat}{periodSuffix}{balanceSuffix}
                        </option>
                      );
                    })}
                  </select>
                  {sf.expense_id && (
                    <SplitExpenseCapacity
                      expenseId={sf.expense_id}
                      expensePeriod={sf.expense_period || null}
                      excludePayoutId={payout?.id}
                      formAllocated={splitForms.reduce((sum, s, idx) => {
                        if (idx === i || s.split_type !== 'expense' || s.expense_id !== sf.expense_id) return sum;
                        if ((s.expense_period || '') !== (sf.expense_period || '')) return sum;
                        return sum + (parseFloat(s.amount_override) || 0);
                      }, 0)}
                      thisRowAmount={parseFloat(sf.amount_override) || 0}
                      onRemainingChange={cap => setSplitMaxByRow(m => (m[i] === cap ? m : { ...m, [i]: cap }))}
                    />
                  )}
                </>
              ) : (
                <>
                  <div className="form-label" style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    Destination
                    {oopLockActive ? <span style={{ color: 'var(--orange)', display: 'inline-flex', alignItems: 'center' }} title="Auto-prefilled from outstanding out-of-pocket. Click Admin override to edit."><LockIcon size={11} /></span> : null}
                  </div>
                  <select aria-label="Destination" className="form-select" value={sf.destination_id} disabled={locked || oopLockActive} onChange={e => setSF(i, 'destination_id', e.target.value)}>
                    <option value="">Select…</option>
                    {destinations.map(d => <option key={d.id} value={d.id}>{d.name} · {d.account_type}{d.account_last4 ? ` ···${d.account_last4}` : ''}{d.institution ? ` (${d.institution})` : ''}</option>)}
                  </select>
                  {isOopRow && !locked ? (
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      onClick={() => setOopUnlockedRows((prev) => {
                        const next = new Set(prev);
                        if (next.has(i)) next.delete(i); else next.add(i);
                        return next;
                      })}
                      style={{ marginTop: 4, fontSize: 10, padding: '2px 6px', color: 'var(--muted)' }}
                    >· {oopUnlocked ? 'Re-lock' : 'Admin override'}</button>
                  ) : null}
                  {isOopRow ? (
                    <div style={{ marginTop: 8 }}>
                      <div className="form-label">Pay it back to</div>
                      <select aria-label="Pay it back to"
                        className="form-select"
                        value={sf.reimbursement_destination_id || ''}
                        disabled={locked}
                        onChange={e => setSF(i, 'reimbursement_destination_id', e.target.value)}
                      >
                        <option value="">Select account…</option>
                        {destinations
                          .filter(d => !d.oop_creator_id && !d.is_deferred && d.is_active !== false)
                          .map(d => <option key={d.id} value={d.id}>{d.name}{d.account_last4 ? ` ···${d.account_last4}` : ''}{d.institution ? ` (${d.institution})` : ''}</option>)}
                      </select>
                      <div style={{ marginTop: 4, fontSize: 11, color: 'var(--muted)', lineHeight: 1.5 }}>
                        Comes out of this payout (not on top). Rides that account's transfer so it lands in a real account, and clears what the LLC owes {parent.creatorName || 'the creator'}.
                      </div>
                    </div>
                  ) : null}
                  {destinations.find(d => d.id === sf.destination_id)?.account_type === 'Other' && (
                    <div style={{ marginTop: 6 }}>
                      <div className="form-label">Notes <span style={{ color: 'var(--dim)', fontWeight: 400, textTransform: 'none', letterSpacing: 0 }}>(shown in place of account type)</span></div>
                      <input aria-label="Split notes" className="form-input" value={sf.notes} maxLength={500} onChange={e => setSF(i, 'notes', e.target.value)} placeholder="e.g. Repay borrowed money" />
                    </div>
                  )}
                </>
              )}
            </div>
            <div className="form-group" style={{ marginBottom: 0 }}>
              <div className="form-label">Percentage / Amount</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <input aria-label="Percentage" className="form-input" type="number" min="0" max="100" step="0.01" value={sf.percentage}
                  disabled={locked || autoLockActive}
                  onChange={e => onPctChange(i, e.target.value, payoutAmt)}
                  style={{ width: 72 }} placeholder="%" />
                <span style={{ color: 'var(--muted)', fontSize: 13 }}>%  =</span>
                <MoneyInput aria-label="Amount"
                  className={'form-input' + (clampedRow === i ? ' is-clamped-flash' : '')}
                  min="0"
                  max={isOopRow ? Math.min(oopOutstanding, payoutAmt || oopOutstanding) : (sf.split_type === 'expense' && splitMaxByRow[i] != null ? splitMaxByRow[i] : undefined)}
                  disabled={locked || autoLockActive}
                  value={sf.amount_override ?? (payoutAmt && sf.percentage ? (payoutAmt * parseFloat(sf.percentage) / 100).toFixed(2) : '')}
                  onChange={e => onAmtChangeClamped(i, e.target.value, payoutAmt)}
                  style={{ width: 90 }} placeholder="$0.00" />
              </div>
            </div>
          </div>
          {/* A recharge row moves no cash: no status, reference, or sent/cleared
              date applies, so those fields are hidden to keep the card compact. */}
          {!isRechargeRow && (<>
          <div className="form-row" style={{ marginBottom: 8 }}>
            <Field label="Split Status" style={{ marginBottom: 0 }}>{(id) => (<>
              <select id={id} className="form-select" value={sf.split_status_id} onChange={e => setSF(i, 'split_status_id', e.target.value)}>
                {splitOptions.map(o => <option key={o.id} value={o.id}>{o.label}</option>)}
              </select>
            </>)}</Field>
            <Field label="Reference / TX ID" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" value={sf.reference} maxLength={200} onChange={e => setSF(i, 'reference', e.target.value)} placeholder="Optional" />
            </>)}</Field>
          </div>
          <div className="form-row" style={{ marginBottom: 0 }}>
            <Field label="Sent Date" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={sf.sent_date} onChange={e => setSF(i, 'sent_date', e.target.value)} />
            </>)}</Field>
            <Field label={<>Cleared Date
                {locked ? <span style={{ color: 'var(--orange)', display: 'inline-flex', alignItems: 'center' }} title="Locked. Reverse the posted entry to change."><LockIcon size={11} /></span> : null}
                {isDeferred && !locked ? <span style={{ color: 'var(--orange2)', display: 'inline-flex', alignItems: 'center' }} title="Deferred destination: cash stays in LLC checking. Cannot clear until the destination is flipped off deferred."><LockIcon size={11} /></span> : null}</>} style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id}
                className="form-input"
                type="date" min={sf.sent_date || DB_DATE_MIN} max={today}
                value={sf.cleared_date}
                onChange={e => setSF(i, 'cleared_date', e.target.value)}
                disabled={locked || isDeferred}
              />
              {isDeferred && !locked ? (
                <div style={{ fontSize: 11, color: 'var(--orange2)', marginTop: 4, lineHeight: 1.4 }}>
                  This destination is deferred. The payout liability stays open; mark cleared only after the cash actually transfers (then uncheck the deferred flag on the destination first).
                </div>
              ) : null}
            </>)}</Field>
          </div>
          </>)}
        </div>
        );
      })}
      {/* Beside the button that produced it. Above the split cards it rendered two viewports
          from the Save that was pressed, on a panel that is already three screens tall. */}
      {error && <Feedback value={error} style={{ marginTop: 12 }} />}
      <SubmitButton saving={saving} className="btn btn-primary w-full mt-12" onClick={save} disabled={saving || negativeSplit >= 0} style={{ justifyContent: 'center' }}>Save Payout</SubmitButton>

      <PostedEntries jes={[...payoutJes, ...Object.values(splitJes)]} title="Posted ledger entries for this payout" onReverse={(je) => setReverseFor(je)} />

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); refetchPayoutJes(); loadAll(); onUpdated(); }}
        />
      ) : null}
    </div>
  );
}
