/** Filing statuses in the order they should appear in a picker. */
export const FILING_STATUSES = [
  { value: 'single',            label: 'Single' },
  { value: 'married_joint',     label: 'Married filing jointly' },
  { value: 'married_separate',  label: 'Married filing separately' },
  { value: 'head_of_household', label: 'Head of household' },
  { value: 'qualifying_widow',  label: 'Qualifying surviving spouse' },
];

export const SE_NET_EARNINGS_FACTOR = 0.9235;  // 100% - half of the 15.3%
export const SE_FLOOR = 400;                   // no SE tax below this
const SS_RATE = 0.124;
const MEDICARE_RATE = 0.029;
const ADDL_MEDICARE_RATE = 0.009;

/** The most recent year we hold rates for. */
export function latestTaxYear() {
  return Math.max(...Object.keys(TAX_YEARS).map((y) => parseInt(y, 10)));
}

/**
 * Rate table for a year, falling back to the latest year we know.
 * @gotcha the fallback keeps the UI computing rather than blanking out when
 *         the calendar rolls into a year nobody has added rates for yet;
 *         `isFallback` lets the caller say so on screen.
 */
export function ratesFor(taxYear) {
  const y = parseInt(taxYear, 10);
  if (TAX_YEARS[y]) return { ...TAX_YEARS[y], year: y, isFallback: false };
  const latest = latestTaxYear();
  return { ...TAX_YEARS[latest], year: latest, isFallback: true };
}

// ── Age ───────────────────────────────────────────────────────

/**
 * Age on Dec 31 of `taxYear`, which is the date the IRS measures dependency
 * and the dependent standard deduction against. Returns null when no birthday
 * is on file.
 */
export function ageAtYearEnd(dateOfBirth, taxYear) {
  if (!dateOfBirth) return null;
  const s = String(dateOfBirth).slice(0, 10);
  const [y, m, d] = s.split('-').map((p) => parseInt(p, 10));
  if (!Number.isFinite(y) || !Number.isFinite(m) || !Number.isFinite(d)) return null;
  // Dec 31 is after every birthday in the year, so the age is simply the
  // difference in years. No month/day comparison needed.
  return taxYear - y;
}

/**
 * True when this person is still a dependent for `taxYear`: under 18 at
 * year end. Patrick's rule, narrower than the IRS qualifying-child test
 * (which reaches 19, or 24 for full-time students).
 */
export function isDependentFor(dateOfBirth, taxYear) {
  const age = ageAtYearEnd(dateOfBirth, taxYear);
  if (age == null) return false;
  return age < 18;
}

// ── Components ────────────────────────────────────────────────

/**
 * Progressive income tax on `taxableIncome`, plus the marginal rate reached.
 * Returns { tax, marginalRate }.
 */
export function incomeTaxOn(taxableIncome, filingStatus, taxYear) {
  const rates = ratesFor(taxYear);
  const brackets = rates.brackets[filingStatus] || rates.brackets.single;
  const income = Math.max(0, num(taxableIncome));
  let tax = 0;
  let lower = 0;
  let marginalRate = brackets[0][1];
  for (const [upper, rate] of brackets) {
    if (income <= lower) break;
    tax += (Math.min(income, upper) - lower) * rate;
    marginalRate = rate;
    lower = upper;
  }
  return { tax: round2(tax), marginalRate };
}

/**
 * Self-employment tax on `netProfit`, given wages that already consumed
 * part of the Social Security wage base.
 *
 * Returns { seTax, netEarnings, socialSecurity, medicare, additionalMedicare,
 *           deductibleHalf }.
 *
 * @gotcha wages matter a lot. Someone whose day job already maxed the Social
 *         Security wage base owes only the 2.9% Medicare portion on their
 *         self-employment income, not the full 15.3%. Ignoring wages
 *         overstates their bill by roughly an eighth of the profit.
 * @invariant no SE tax at all when net earnings fall under SE_FLOOR ($400),
 *            per IRC 1402(b).
 */
export function selfEmploymentTax(netProfit, { wages = 0, filingStatus = 'single', taxYear } = {}) {
  const rates = ratesFor(taxYear);
  const profit = Math.max(0, num(netProfit));
  const netEarnings = round2(profit * SE_NET_EARNINGS_FACTOR);

  const zero = {
    seTax: 0, netEarnings, socialSecurity: 0, medicare: 0,
    additionalMedicare: 0, deductibleHalf: 0,
  };
  if (netEarnings < SE_FLOOR) return zero;

  const w = Math.max(0, num(wages));
  const ssRoom = Math.max(0, rates.socialSecurityWageBase - w);
  const socialSecurity = round2(Math.min(netEarnings, ssRoom) * SS_RATE);
  const medicare = round2(netEarnings * MEDICARE_RATE);

  // Additional Medicare applies to combined wages + SE earnings over the
  // threshold, and is NOT halved into the deductible portion.
  const threshold = rates.additionalMedicareThreshold[filingStatus]
    || rates.additionalMedicareThreshold.single;
  const over = Math.max(0, (w + netEarnings) - threshold);
  const additionalMedicare = round2(Math.min(over, netEarnings) * ADDL_MEDICARE_RATE);

  const seTax = round2(socialSecurity + medicare + additionalMedicare);
  return {
    seTax,
    netEarnings,
    socialSecurity,
    medicare,
    additionalMedicare,
    deductibleHalf: round2((socialSecurity + medicare) / 2),
  };
}

/**
 * Standard deduction for the year, using the dependent formula when the person
 * is still a dependent.
 * Returns { amount, isDependent }.
 *
 * @gotcha a dependent's deduction is earned income + a bump, floored at
 *         dependentFloor and capped at the regular deduction. Self-employment
 *         income counts as earned income for this test, so a creator earning
 *         $8,000 gets $8,450, not the $1,350 floor.
 */
export function standardDeductionFor({ filingStatus = 'single', earnedIncome = 0, dependent = false, taxYear }) {
  const rates = ratesFor(taxYear);
  const regular = rates.standardDeduction[filingStatus] ?? rates.standardDeduction.single;
  if (!dependent) return { amount: regular, isDependent: false };
  const earned = Math.max(0, num(earnedIncome));
  const amount = Math.min(regular, Math.max(rates.dependentFloor, earned + rates.dependentEarnedBump));
  return { amount: round2(amount), isDependent: true };
}

// ── The estimate ──────────────────────────────────────────────

/**
 * Federal tax on a given total income. Internal: the estimate never SHOWS this,
 * it only differences two of them.
 */
function liabilityOn({ taxYear, otherIncome, nysterysIncome, seIncome, wages, filingStatus, dependent }) {
  // Only the self-employed slice carries SE tax, and so only it carries a deductible half: the
  // taxable income of an earner is a touch HIGHER than a contractor's on the same gross, which
  // is why the switch never saves quite the whole SE tax.
  const se = selfEmploymentTax(seIncome, { wages, filingStatus, taxYear });
  const { amount: standardDeduction } = standardDeductionFor({
    filingStatus, earnedIncome: nysterysIncome, dependent, taxYear,
  });
  const adjustedGrossIncome = round2(otherIncome + nysterysIncome - se.deductibleHalf);
  const taxableIncome = round2(Math.max(0, adjustedGrossIncome - standardDeduction));
  const { tax, marginalRate } = incomeTaxOn(taxableIncome, filingStatus, taxYear);
  return { se, standardDeduction, adjustedGrossIncome, taxableIncome, incomeTax: tax, marginalRate };
}

/**
 * Estimate the federal tax ONE PERSON owes because of their Nysterys income, for `taxYear`.
 *
 * Not their whole bill: the difference between owing with this income and without it, plus its
 * self-employment tax. Their day job's tax is already withheld from their paycheck.
 *
 * @param {object} input
 * @param {number} input.taxYear         - the year being estimated.
 * @param {number} input.nysterysIncome  - year-to-date income from Nysterys: a partner's share
 *        of ordinary business income, or a creator's 1099-NEC basis.
 * @param {string} [input.dateOfBirth]   - drives the dependent deduction.
 * @param {object} [input.basis]         - the prior return { tax_year, filing_status, agi,
 *        wages }, used ONLY to place the bracket and see how much Social Security base is left.
 *        Absent means Nysterys is assumed to be their only income.
 * @param {number} [input.basisNysterysIncome] - what Nysterys paid in the basis year,
 *        subtracted out of AGI so it is not counted twice.
 * @param {number} [input.selfEmploymentIncome] - how much of `nysterysIncome` was paid on days
 *        the person was a contractor. Defaults to all of it. A creator on wages passes 0, and a
 *        creator whose year holds both passes the 1099 slice. Partners are ALWAYS
 *        self-employed: one cannot be an employee of their own partnership, so a partner passes
 *        nothing and takes the default.
 * @param {number} [input.withheld] - federal income tax Nysterys itself withheld on this
 *        income, in this year. Never a prior return's withholding. @see the file header.
 * @returns {object} the figures a tax surface renders, including setAside, and the wage and
 *          self-employed halves of the income it was worked out on.
 *
 * @invariant totalTax === incomeTax + seTax. setAside is totalTax LESS `withheld`, floored at
 *            zero, so it is what is still to find rather than what is owed. They are the same
 *            number only when nothing was withheld.
 * @invariant zero Nysterys income means zero tax, whatever else the person earns.
 * @gotcha `withheld` is the tax on THIS income and nothing else. A prior return's withholding
 *         pays for the outside income this figure already excludes, so subtracting that would
 *         credit the same dollars twice.
 * @gotcha the dependent standard deduction is measured against the WHOLE income, wage slice
 *         included, because both halves are earned income for that test.
 * @gotcha otherIncome floors at zero after subtracting the basis year's Nysterys income, or a
 *         partner's share is counted inside AGI and again as current income.
 */
export function estimatePersonTax({
  taxYear,
  nysterysIncome = 0,
  dateOfBirth = null,
  basis = null,
  basisNysterysIncome = 0,
  selfEmploymentIncome = null,
  withheld = 0,
} = {}) {
  const year = parseInt(taxYear, 10);
  const income = round2(Math.max(0, num(nysterysIncome)));
  // Clamped into the income it is a slice OF, so a caller that hands over a stale or larger
  // figure cannot conjure self-employment tax on dollars nobody was paid.
  const seIncome = selfEmploymentIncome == null
    ? income
    : round2(Math.min(income, Math.max(0, num(selfEmploymentIncome))));
  const filingStatus = basis?.filing_status || 'single';
  const wages = num(basis?.wages);
  const basisYear = basis?.tax_year != null ? parseInt(basis.tax_year, 10) : null;
  const dependent = isDependentFor(dateOfBirth, year);

  const otherIncome = basis
    ? Math.max(0, round2(num(basis.agi) - num(basisNysterysIncome)))
    : 0;

  const common = { taxYear: year, otherIncome, wages, filingStatus, dependent };
  const withIt    = liabilityOn({ ...common, nysterysIncome: income, seIncome });
  const withoutIt = liabilityOn({ ...common, nysterysIncome: 0, seIncome: 0 });

  const incomeTax = round2(Math.max(0, withIt.incomeTax - withoutIt.incomeTax));
  const seTax = withIt.se.seTax;
  const totalTax = round2(incomeTax + seTax);
  const taken = round2(Math.max(0, num(withheld)));

  return {
    taxYear: year,
    filingStatus,
    nysterysIncome: income,
    selfEmploymentIncome: seIncome,
    wageIncome: round2(income - seIncome),
    otherIncome,
    wages: round2(wages),
    se: withIt.se,
    seTax,
    standardDeduction: withIt.standardDeduction,
    isDependent: dependent,
    taxableIncome: withIt.taxableIncome,
    incomeTax,
    marginalRate: withIt.marginalRate,
    totalTax,
    withheld: taken,
    // Floored, because Gusto annualizes each month in isolation and can easily withhold more
    // than a part year owes. A negative set-aside would read as a refund this tool does not
    // model: it excludes the outside income any refund would actually be computed against.
    setAside: round2(Math.max(0, totalTax - taken)),
    basisYear,
    hasBasis: !!basis,
    isStaleBasis: !!basis && basisYear != null && basisYear < year - 1,
  };
}

/**
 * Estimate what a JOINT return owes because of its Nysterys income.
 *
 * A married-filing-jointly couple is one taxpayer for income tax and two
 * taxpayers for self-employment tax. Same incremental rule as
 * estimatePersonTax: the couple's outside income only decides which bracket the
 * Nysterys income lands in; the tax on that outside income is not this tool's
 * business.
 *
 * @param {object} input
 * @param {number} input.taxYear
 * @param {Array} input.members - one entry per person on the return:
 *        { profile, nysterysIncome, basisNysterysIncome, wages }.
 * @param {object} [input.basis] - the household's return row: { tax_year,
 *        filing_status, agi }. `wages` on it is ignored; each member carries
 *        their own, because the Social Security wage base is individual even on
 *        a joint return.
 *
 * @returns {object} the shape estimatePersonTax returns, plus
 *          `members: [{ profile, nysterysIncome, se }]`.
 *
 * @invariant income tax is differenced ONCE for the pair; self-employment tax
 *            is summed per person. Estimating each spouse separately and adding
 *            the results applies the joint deduction and the low brackets twice.
 * @invariant a partner's income is self-employment income in every year and nothing withholds
 *            on it, so `setAside` is the whole `totalTax` here and there is no wage half. The
 *            two fields are returned all the same, so one renderer reads both shapes.
 * @gotcha otherIncome subtracts EVERY member's basis-year Nysterys income from
 *         the joint AGI, not just one.
 */
export function estimateHouseholdTax({ taxYear, members = [], basis = null } = {}) {
  const year = parseInt(taxYear, 10);
  const filingStatus = basis?.filing_status || 'married_joint';
  const basisYear = basis?.tax_year != null ? parseInt(basis.tax_year, 10) : null;

  const each = members.map((m) => {
    const income = round2(Math.max(0, num(m.nysterysIncome)));
    return {
      profile: m.profile,
      nysterysIncome: income,
      se: selfEmploymentTax(income, { wages: num(m.wages), filingStatus, taxYear: year }),
    };
  });

  const nysterysIncome = round2(each.reduce((s, m) => s + m.nysterysIncome, 0));
  const seTax          = round2(each.reduce((s, m) => s + m.se.seTax, 0));
  const deductibleHalf = round2(each.reduce((s, m) => s + m.se.deductibleHalf, 0));
  const basisShare     = members.reduce((s, m) => s + num(m.basisNysterysIncome), 0);

  const otherIncome = basis ? Math.max(0, round2(num(basis.agi) - basisShare)) : 0;

  // Nobody on a joint return is somebody else's dependent.
  const { amount: standardDeduction } = standardDeductionFor({
    filingStatus, dependent: false, taxYear: year,
  });

  const taxableWith    = round2(Math.max(0, otherIncome + nysterysIncome - deductibleHalf - standardDeduction));
  const taxableWithout = round2(Math.max(0, otherIncome - standardDeduction));
  const withIt    = incomeTaxOn(taxableWith,    filingStatus, year);
  const withoutIt = incomeTaxOn(taxableWithout, filingStatus, year);

  const incomeTax = round2(Math.max(0, withIt.tax - withoutIt.tax));
  const totalTax = round2(incomeTax + seTax);

  return {
    taxYear: year,
    filingStatus,
    isHousehold: true,
    members: each,
    nysterysIncome,
    selfEmploymentIncome: nysterysIncome,
    wageIncome: 0,
    otherIncome,
    wages: round2(members.reduce((s, m) => s + num(m.wages), 0)),
    se: { deductibleHalf, seTax },
    seTax,
    standardDeduction,
    isDependent: false,
    taxableIncome: taxableWith,
    incomeTax,
    marginalRate: withIt.marginalRate,
    totalTax,
    withheld: 0,
    setAside: totalTax,
    basisYear,
    hasBasis: !!basis,
    isStaleBasis: !!basis && basisYear != null && basisYear < year - 1,
  };
}

/**
 * Sum a list of per-person estimates into the household figures.
 * @invariant the total is the sum of the rendered rows, never an independently
 *            derived figure, so the foot line can never disagree with the list.
 */
export function sumEstimates(estimates) {
  const list = (estimates || []).filter(Boolean);
  return {
    count: list.length,
    nysterysIncome: round2(list.reduce((s, e) => s + num(e.nysterysIncome), 0)),
    incomeTax:      round2(list.reduce((s, e) => s + num(e.incomeTax), 0)),
    seTax:          round2(list.reduce((s, e) => s + num(e.seTax), 0)),
    totalTax:       round2(list.reduce((s, e) => s + num(e.totalTax), 0)),
    setAside:       round2(list.reduce((s, e) => s + num(e.setAside), 0)),
  };
}

/** Human label for a filing status value. */
export function filingStatusLabel(value) {
  return FILING_STATUSES.find((f) => f.value === value)?.label || 'Single';
}

/** Marginal rate as a display percentage, e.g. 0.22 becomes "22%". */
export function formatRate(rate) {
  return `${Math.round(num(rate) * 100)}%`;
}
