/**
 * components/shared/OverviewPage.js. Landing dashboard shared by admin and creator.
 *
 * One component for both roles. Admin (isAdmin=true, profileId=null,
 * creatorName=null) sees all creators, filterable; creator (isAdmin=false,
 * profileId=<uuid>, creatorName="Mys") sees only their own data.
 *
 * Admin-only differences: creator filter chips, the Creator column in tables, the
 * Agency-pending + Payouts-pending sections, and the "You Received" / "Paid to
 * Creators" labels (vs creator's "Agency Paid" / "Paid to Me"). creatorFilter
 * applies to EVERY section on the page (campaigns, summary, rewards).
 *
 * @gotcha Money figures here are display rollups off campaign_payout_summary +
 *         reward_payout_summary filtered by period; they are NOT recognized
 *         revenue and do NOT tie to the ledger or to MyMoneyPage's "You made".
 *         Different bases never equal. @see docs/MONEY.md (reconciliation bases).
 */
import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { ChevronIcon } from './Icon';
import Badge from './Badge';
import { fmtDate, fmtMoney, extractMonths, isInKind } from '../../utils/format';
import { campaignLabelParts } from '../../utils/campaignLabel';
import CampaignName from './CampaignName';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { inPeriod, PeriodSelect } from '../../utils/period';
import { receivedTotal } from '../../utils/invoiceMath';
import CreatorFilterChips from './CreatorFilterChips';
import { useCreators } from '../../hooks/useCreators';
import ReadError from './ReadError';
import PlatformReach from './PlatformReach';
import { activationProps } from '../../utils/rowActivation';
import Loading from './Loading';

// ── Financial summary table ────────────────────────────────────────────────────

/**
 * Period-filtered money summary: campaign payments + reward groups, one row per
 * platform/program. Renders a simplified 4-column table for creators (Source /
 * Earned / Paid to Me / Pending) and the full 8-column table for admins.
 *
 * @param {boolean} props.fitContent - size the table to its content rather than to
 *        the box, so the eight columns keep their width on a phone instead of
 *        squeezing to min-content. The box scrolls either way.
 * @gotcha In-kind rows are split out (isInKind) and summed separately as FMV;
 *         they never count toward cash contracted/received/paid totals.
 */
function FinancialTable({ summaryRows, rewardRows, period, isAdmin, fitContent }) {
  const filtSummary = summaryRows.filter(r => {
    const dateRef = r.invoice_date || r.payout_date;
    if (!dateRef) return true;
    return inPeriod(dateRef, period);
  });

  const cashRows    = filtSummary.filter(r => !isInKind(r.is_in_kind));
  const contracted  = cashRows.reduce((s, r) => s + (r.contracted_rate || 0), 0);
  const received    = receivedTotal(cashRows);
  const pendReceipt = cashRows.filter(r => !r.you_received).reduce((s, r) => s + (r.contracted_rate || 0), 0);
  const paidOut     = cashRows.filter(r => r.payout_status === 'Paid').reduce((s, r) => s + (r.payout_amount || 0), 0);
  const pendPayout  = cashRows.filter(r => r.payout_status !== 'Paid' && r.payout_status !== 'N/A' && r.you_received).reduce((s, r) => s + (r.payout_amount || r.contracted_rate || 0), 0);
  const fees        = cashRows.reduce((s, r) => s + (r.processing_fee || 0), 0);
  const inKind      = filtSummary.filter(r => isInKind(r.is_in_kind)).reduce((s, r) => s + (r.invoice_amount ?? r.contracted_rate ?? 0), 0);

  const filtRewards  = rewardRows.filter(e => inPeriod(e.period_month, period));
  const rewardGroups = Object.values(filtRewards.reduce((acc, e) => {
    const key = `${e.platform_name || 'Platform'}||${e.program_name}`;
    if (!acc[key]) acc[key] = { platform: e.platform_name || 'Platform', program: e.program_name, entries: [] };
    acc[key].entries.push(e);
    return acc;
  }, {}));

  const cs  = { padding: '12px 14px', verticalAlign: 'middle' };
  const ns  = (c) => ({ ...cs, fontWeight: 600, color: c || 'var(--white)', textAlign: 'right', whiteSpace: 'nowrap' });
  const ds  = { ...cs, color: 'var(--muted)', textAlign: 'right' };
  const ls  = { ...cs, fontWeight: 600, fontSize: 13 };
  const sub = { fontSize: 10, color: 'var(--muted)', fontWeight: 400, display: 'block', marginTop: 2, letterSpacing: 0.3 };
  const thS = { padding: '9px 14px', fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1.5, color: 'var(--dim)', textAlign: 'right', borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap' };
  const thL = { ...thS, textAlign: 'left' };

  // ── Creator simplified view ──────────────────────────────────────────────────
  if (!isAdmin) {
    const Dash = () => <span style={{ color: 'var(--dim)' }}>—</span>;
    const Num  = ({ v, color }) => (!v || v === 0) ? <Dash /> : <span style={{ color, fontWeight: 600 }}>{fmtMoney(v)}</span>;

    const rEarned  = rewardGroups.reduce((s, g) => s + g.entries.reduce((ss, e) => ss + (e.gross_amount || 0), 0), 0);
    const rPaid    = rewardGroups.reduce((s, g) => s + g.entries.filter(e => e.payout_status === 'Paid').reduce((ss, e) => ss + (e.payout_amount || 0), 0), 0);
    const rPending = rewardGroups.reduce((s, g) => s + g.entries.filter(e => e.payout_status !== 'Paid' && e.you_received).reduce((ss, e) => ss + (e.payout_amount || e.gross_amount || 0), 0), 0);

    const tEarned  = contracted + rEarned;
    const tPaid    = paidOut + rPaid;
    const tPending = pendPayout + rPending;

    const rows = [
      { label: 'Campaign Payments', sub: 'Brand deals', earned: contracted, paid: paidOut, pending: pendPayout },
      ...rewardGroups.map(g => ({
        label: g.platform, sub: g.program,
        earned: g.entries.reduce((s, e) => s + (e.gross_amount || 0), 0),
        paid:   g.entries.filter(e => e.payout_status === 'Paid').reduce((s, e) => s + (e.payout_amount || 0), 0),
        pending: g.entries.filter(e => e.payout_status !== 'Paid' && e.you_received).reduce((s, e) => s + (e.payout_amount || e.gross_amount || 0), 0),
      })),
    ];

    return (
      <div className="table-wrap" style={{ marginBottom: 24 }}>
        <table style={{ width: fitContent ? 'max-content' : '100%', minWidth: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ background: 'var(--surface2)' }}>
              <th scope="col" style={thL}>Source</th>
              <th scope="col" style={thS}>Earned</th>
              <th scope="col" style={thS}>Paid to Me</th>
              <th scope="col" style={thS}>Pending</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr key={i} style={{ borderBottom: i < rows.length - 1 ? '1px solid var(--border)' : 'none', background: i % 2 === 0 ? 'var(--surface)' : 'var(--surface2)' }}>
                <td style={ls}>{r.label}<span style={sub}>{r.sub}</span></td>
                <td style={ns()}><Num v={r.earned} color="var(--white)" /></td>
                <td style={ns('var(--green)')}><Num v={r.paid} color="var(--green)" /></td>
                <td style={ns('var(--orange2)')}><Num v={r.pending} color="var(--orange2)" /></td>
              </tr>
            ))}
            {rows.length > 1 && (
              <tr style={{ borderTop: '2px solid var(--border2)', background: 'var(--surface2)' }}>
                <td style={{ ...ls, color: 'var(--muted)', fontSize: 11, letterSpacing: 1, textTransform: 'uppercase' }}>Total</td>
                <td style={ns()}><Num v={tEarned} color="var(--white)" /></td>
                <td style={ns('var(--green)')}><Num v={tPaid} color="var(--green)" /></td>
                <td style={ns('var(--orange2)')}><Num v={tPending} color="var(--orange2)" /></td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    );
  }

  const Dash = () => <span style={{ color: 'var(--dim)' }}>—</span>;
  const Num  = ({ v, color }) =>
    (!v || v === 0) ? <Dash /> :
    <span style={{ color }}>{fmtMoney(v)}</span>;

  function RewardGroupRow({ g, i, isLast }) {
    const gross   = g.entries.reduce((s, e) => s + (e.gross_amount || 0), 0);
    const recvd   = receivedTotal(g.entries);
    const pndRcpt = g.entries.filter(e => !e.you_received).reduce((s, e) => s + (e.gross_amount || 0), 0);
    const paid    = g.entries.filter(e => e.payout_status === 'Paid').reduce((s, e) => s + (e.payout_amount || 0), 0);
    const pend    = g.entries.filter(e => e.payout_status !== 'Paid' && e.you_received).reduce((s, e) => s + (e.payout_amount || e.gross_amount || 0), 0);
    const rgFees  = g.entries.reduce((s, e) => s + (e.processing_fee || 0), 0);
    return (
      <tr style={{ borderBottom: isLast ? 'none' : '1px solid var(--border)', background: i % 2 === 0 ? 'var(--surface)' : 'var(--surface2)' }}>
        <td style={ls}>{g.platform}<span style={sub}>{g.program}</span></td>
        <td style={ns()}><Num v={gross} color="var(--white)" /></td>
        <td style={ns('var(--green)')}><Num v={recvd} color="var(--green)" /></td>
        <td style={ns('var(--orange)')}><Num v={pndRcpt} color="var(--orange)" /></td>
        <td style={ns('var(--blue)')}><Num v={paid} color="var(--blue)" /></td>
        <td style={ns('var(--orange)')}><Num v={pend} color="var(--orange)" /></td>
        <td style={ns('var(--red)')}><Num v={rgFees} color="var(--red)" /></td>
        <td style={ds}><Dash /></td>
      </tr>
    );
  }

  const tGross   = contracted + rewardGroups.reduce((s, g) => s + g.entries.reduce((ss, e) => ss + (e.gross_amount || 0), 0), 0);
  const tRecvd   = received   + rewardGroups.reduce((s, g) => s + receivedTotal(g.entries), 0);
  const tPndRcpt = pendReceipt + rewardGroups.reduce((s, g) => s + g.entries.filter(e => !e.you_received).reduce((ss, e) => ss + (e.gross_amount || 0), 0), 0);
  const tPaid    = paidOut    + rewardGroups.reduce((s, g) => s + g.entries.filter(e => e.payout_status === 'Paid').reduce((ss, e) => ss + (e.payout_amount || 0), 0), 0);
  const tPend    = pendPayout + rewardGroups.reduce((s, g) => s + g.entries.filter(e => e.payout_status !== 'Paid' && e.you_received).reduce((ss, e) => ss + (e.payout_amount || e.gross_amount || 0), 0), 0);
  const tFees    = fees       + rewardGroups.reduce((s, g) => s + g.entries.reduce((ss, e) => ss + (e.processing_fee || 0), 0), 0);

  return (
    <div className="table-wrap" style={{ marginBottom: 24 }}>
      <table style={{ width: fitContent ? 'max-content' : '100%', minWidth: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ background: 'var(--surface2)' }}>
            <th scope="col" style={thL}>Source</th>
            <th scope="col" style={thS}>Contracted / Gross</th>
            <th scope="col" style={thS}>{isAdmin ? 'You Received' : 'Agency Paid'}</th>
            <th scope="col" style={thS}>Pending Receipt</th>
            <th scope="col" style={thS}>{isAdmin ? 'Paid to Creators' : 'Paid to Me'}</th>
            <th scope="col" style={thS}>Pending Payout</th>
            <th scope="col" style={thS}>Fees</th>
            <th scope="col" style={thS}>In-Kind FMV</th>
          </tr>
        </thead>
        <tbody>
          <tr style={{ borderBottom: rewardGroups.length > 0 ? '1px solid var(--border)' : 'none', background: 'var(--surface)' }}>
            <td style={ls}>Campaign Payments<span style={sub}>Brand deals</span></td>
            <td style={ns()}><Num v={contracted} color="var(--white)" /></td>
            <td style={ns('var(--green)')}><Num v={received} color="var(--green)" /></td>
            <td style={ns('var(--orange)')}><Num v={pendReceipt} color="var(--orange)" /></td>
            <td style={ns('var(--blue)')}><Num v={paidOut} color="var(--blue)" /></td>
            <td style={ns('var(--orange)')}><Num v={pendPayout} color="var(--orange)" /></td>
            <td style={ns('var(--red)')}><Num v={fees} color="var(--red)" /></td>
            <td style={ds}><Num v={inKind} color="var(--muted)" /></td>
          </tr>
          {rewardGroups.map((g, i) => (
            <RewardGroupRow key={`${g.platform}-${g.program}`} g={g} i={i} isLast={i === rewardGroups.length - 1} />
          ))}
          {rewardGroups.length > 0 && (
            <tr style={{ borderTop: '2px solid var(--border2)', background: 'var(--surface2)' }}>
              <td style={{ ...ls, color: 'var(--muted)', fontSize: 11, letterSpacing: 1, textTransform: 'uppercase' }}>Total</td>
              <td style={ns()}><Num v={tGross} color="var(--white)" /></td>
              <td style={ns('var(--green)')}><Num v={tRecvd} color="var(--green)" /></td>
              <td style={ns('var(--orange)')}><Num v={tPndRcpt} color="var(--orange)" /></td>
              <td style={ns('var(--blue)')}><Num v={tPaid} color="var(--blue)" /></td>
              <td style={ns('var(--orange)')}><Num v={tPend} color="var(--orange)" /></td>
              <td style={ns('var(--red)')}><Num v={tFees} color="var(--red)" /></td>
              <td style={ds}><Num v={inKind} color="var(--muted)" /></td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

// ── Main shared component ──────────────────────────────────────────────────────

/**
 * Overview page. @see file header for the admin/creator split and money-base caveat.
 *
 * @param {boolean} props.isAdmin
 * @param {?string} props.profileId - creator's uuid; scopes all three fetches.
 * @param {?string} props.creatorName - greeting name for the creator title.
 * @param {function} props.setActiveView - section navigation fallback.
 * @param {function} [props.navigateToCampaign] - open a campaign detail directly.
 * @param {function} [props.navigateToDeliverable] - open a deliverable directly.
 * @param {number} props.refreshKey - bump to force a re-fetch from the parent.
 */
export default function OverviewPage({ isAdmin, profileId, creatorName, setActiveView, navigateToCampaign, navigateToDeliverable, refreshKey }) {
  const { options: statusOptions } = useStatusOptions();
  const campText  = id => (statusOptions.campaign    || []).find(o => o.id === id)?.value || null;
  const delivText = id => (statusOptions.deliverable || []).find(o => o.id === id)?.value || null;
  const invText   = id => (statusOptions.payment     || []).find(o => o.id === id)?.value || null;
  const poText    = id => (statusOptions.payout      || []).find(o => o.id === id)?.value || null;
  const [campaigns, setCampaigns]         = useState([]);
  const [summaryRows, setSummaryRows]     = useState([]);
  const [rewardRows, setRewardRows]       = useState([]);
  const { creators } = useCreators(isAdmin);
  const [creatorFilter, setCreatorFilter] = useState('all');
  const [loading, setLoading]             = useState(true);
  // The third state. This is the default view on first load for BOTH roles, and its answer is
  // a sum of three reads: a refused one drops out of the total silently and the page still
  // says "All clear", which is the one sentence it must not say when it cannot see the work.
  const [loadError, setLoadError]         = useState(null);
  // All time, not the current month: this is the page both roles land on, and a window that
  // opens on the 6th of a quiet month greets them with zeroes for work that has been done and
  // paid. The period is a question the reader asks, never one the page assumes.
  const [period, setPeriod]               = useState('all');
  const [expandedAttention, setExpandedAttention] = useState(null);
  const [isMobile, setIsMobile] = useState(() => window.innerWidth <= 768);

  useEffect(() => { fetchAll(); }, []);
  useEffect(() => { if (refreshKey > 0) fetchAll(); }, [refreshKey]);
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  /**
   * Load campaigns (with deliverables/invoices/payouts), the campaign payout
   * summary, and the reward payout summary in parallel. Creator scope is applied
   * to all three when not admin. Cancelled campaigns are excluded from the
   * summary view.
   * @gotcha The two *_payout_summary views are security_invoker + anon-revoked,
   *         so RLS auto-scopes them to the caller; the explicit creator_profile_id
   *         filter is an additional narrowing, not the security boundary.
   *         @see docs/CODEBASE.md (RLS).
   */
  async function fetchAll() {
    setLoadError(null);
    let campaignQuery = supabase.from('campaigns').select(`
      id, campaign_name, display_name, brand_name, contracted_rate, status_id, creator_profile_id,
      campaign_start_date, campaign_end_date, deal_signed_date,
      agency:agencies(name),
      creator:profiles!campaigns_creator_profile_id_fkey(full_name, creator_name),
      campaign_deliverables(id, draft_status_id, contracted_post_date,
        platform:platforms(name), deliverable_type:deliverable_types(name)),
      invoices(payment_status_id, is_in_kind),
      creator_payouts(payout_status_id, payout_amount)
    `).order('created_at', { ascending: false });

    let summaryQuery = supabase.from('campaign_payout_summary').select(
      'campaign_id, creator_profile_id, contracted_rate, is_in_kind, payment_method, agency_payment_status, agency_payment_status_id, invoice_date, ' +
      'invoice_amount, amount_received, processing_fee, you_received, you_received_date, ' +
      'payout_status, payout_status_id, payout_amount, payout_date'
    ).neq('status', 'Cancelled');

    let rewardQuery = supabase.from('reward_payout_summary').select(
      'entry_id, profile_id, platform_name, program_name, period_month, gross_amount, ' +
      'amount_received, invoice_amount, processing_fee, you_received, ' +
      'payout_status, payout_status_id, payout_amount'
    ).order('period_month', { ascending: false });

    if (!isAdmin && profileId) {
      campaignQuery = campaignQuery.eq('creator_profile_id', profileId);
      summaryQuery  = summaryQuery.eq('creator_profile_id', profileId);
      rewardQuery   = rewardQuery.eq('profile_id', profileId);
    }

    const [cRes, sRes, rRes] = await Promise.all([campaignQuery, summaryQuery, rewardQuery]);

    const readError = cRes.error || sRes.error || rRes.error;
    if (readError) {
      setLoadError(readError);
      setCampaigns([]);
      setSummaryRows([]);
      setRewardRows([]);
      setLoading(false);
      return;
    }
    setCampaigns(cRes.data   || []);
    setSummaryRows(sRes.data || []);
    setRewardRows(rRes.data  || []);
    setLoading(false);
  }

  // ── Apply creatorFilter to ALL data ─────────────────────────────────────────
  const viewCampaigns   = useMemo(
    () => ((isAdmin && creatorFilter !== 'all')
      ? campaigns.filter(c => c.creator_profile_id === creatorFilter)
      : campaigns),
    [isAdmin, creatorFilter, campaigns]
  );
  const viewSummaryRows = useMemo(
    () => ((isAdmin && creatorFilter !== 'all')
      ? summaryRows.filter(r => r.creator_profile_id === creatorFilter)
      : summaryRows),
    [isAdmin, creatorFilter, summaryRows]
  );
  const viewRewardRows  = useMemo(
    () => ((isAdmin && creatorFilter !== 'all')
      ? rewardRows.filter(r => r.profile_id === creatorFilter)
      : rewardRows),
    [isAdmin, creatorFilter, rewardRows]
  );

  // ── Derived activity data ────────────────────────────────────────────────────
  const active   = useMemo(
    () => viewCampaigns.filter(c => campText(c.status_id) === 'Active'),
    [viewCampaigns, statusOptions]
  );
  const needsAttentionGrouped = useMemo(
    () => Object.values(
      viewCampaigns
        .filter(c => campText(c.status_id) === 'Active')
        .flatMap(c =>
          (c.campaign_deliverables || [])
            .filter(d => ['Not Started', 'Revisions Requested'].includes(delivText(d.draft_status_id)))
            .map(d => ({ ...d, campaign: c }))
        )
        .reduce((acc, d) => {
          if (!acc[d.campaign.id]) acc[d.campaign.id] = { campaign: d.campaign, items: [] };
          acc[d.campaign.id].items.push(d);
          return acc;
        }, {})
    ),
    [viewCampaigns, statusOptions]
  );

  // Admin-only pending sections.
  // agencyPending: cash campaigns whose invoice is still unpaid (Not Invoiced /
  // Invoiced / Pending) and not Cancelled. In-kind campaigns are excluded (no cash).
  const agencyPending = useMemo(
    () => (isAdmin ? viewCampaigns.filter(c => {
      const inv = c.invoices?.[0];
      if (!inv || isInKind(inv.is_in_kind)) return false;
      return ['Not Invoiced', 'Invoiced', 'Pending'].includes(invText(inv.payment_status_id)) && campText(c.status_id) !== 'Cancelled';
    }) : []),
    [isAdmin, viewCampaigns, statusOptions]
  );

  // payoutsPending: cash campaigns the agency has begun/finished paying (invoice
  // Invoiced/Pending/Paid) but where the creator payout is not yet Paid.
  const payoutsPending = useMemo(
    () => (isAdmin ? viewCampaigns.filter(c => {
      const inv    = c.invoices?.[0];
      if (isInKind(inv?.is_in_kind)) return false;
      const payout = c.creator_payouts?.[0];
      return inv && ['Invoiced', 'Pending', 'Paid'].includes(invText(inv.payment_status_id)) &&
             campText(c.status_id) !== 'Cancelled' && (!payout || poText(payout.payout_status_id) !== 'Paid');
    }) : []),
    [isAdmin, viewCampaigns, statusOptions]
  );

  // Period dropdown options
  const campaignMonths = useMemo(() => extractMonths(viewSummaryRows, 'invoice_date'), [viewSummaryRows]);
  const rewardMonths   = useMemo(() => extractMonths(viewRewardRows, 'period_month'),   [viewRewardRows]);
  const allMonths      = useMemo(
    () => [...new Set([...campaignMonths, ...rewardMonths])].sort().reverse(),
    [campaignMonths, rewardMonths]
  );

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  function navigateCampaign(id) {
    if (navigateToCampaign) navigateToCampaign(id);
    else if (setActiveView) setActiveView('campaigns');
  }

  function navToDeliverable(campaignId, deliverableId) {
    if (navigateToDeliverable) navigateToDeliverable(campaignId, deliverableId);
    else navigateCampaign(campaignId);
  }

  const selectedCreatorName = creatorFilter !== 'all'
    ? (creators.find(c => c.id === creatorFilter)?.creator_name || creators.find(c => c.id === creatorFilter)?.full_name || '')
    : null;

  const hasUrgent = needsAttentionGrouped.length > 0;

  const pageTitle    = isAdmin ? 'OVERVIEW' : `HEY, ${(creatorName || '').toUpperCase()}`;
  const pageSubtitle = isAdmin
    ? (selectedCreatorName ? `${selectedCreatorName}'s campaigns` : 'All campaigns across Kym and Mys')
    : (hasUrgent ? "Here's what needs your attention" : "You're all caught up");

  const allClear = !hasUrgent && active.length === 0 &&
                   agencyPending.length === 0 && payoutsPending.length === 0;

  // ── Mobile render ─────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <div className="page">

        {/* Mobile header: title row + controls row */}
        <div style={{ marginBottom: 20 }}>
          <div style={{ marginBottom: 8 }}>
            <h1 className="page-title">{pageTitle}</h1>
            <div className="page-subtitle">{pageSubtitle}</div>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>
            {isAdmin && creators.length > 0 && (
              <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            )}
            <PeriodSelect period={period} onChange={setPeriod} months={allMonths} style={{ padding: '6px 10px', fontSize: 13 }} />
          </div>
        </div>

        {/* 1. Needs Attention */}
        {hasUrgent && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
              <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: '3.5px', textTransform: 'uppercase', color: 'var(--orange)' }}>
                {needsAttentionGrouped.length} {needsAttentionGrouped.length === 1 ? 'campaign needs' : 'campaigns need'} action
              </span>
              <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('campaigns')}>Go to Campaigns →</button>
            </div>
            <div style={{ border: '1px solid rgba(255,92,0,0.2)', borderRadius: 6, overflow: 'hidden' }}>
              {needsAttentionGrouped.map(({ campaign, items }, idx) => {
                const isExpanded = expandedAttention === null ? idx === 0 : expandedAttention === campaign.id;
                const earliest = items
                  .filter(d => d.contracted_post_date)
                  .sort((a, b) => a.contracted_post_date > b.contracted_post_date ? 1 : -1)[0];
                const { label, month } = campaignLabelParts(campaign);
                const creator = campaign.creator?.creator_name || campaign.creator?.full_name;
                return (
                  <div key={campaign.id} style={{ borderBottom: idx < needsAttentionGrouped.length - 1 ? '1px solid var(--border)' : 'none' }}>
                    <div
                      style={{
                        padding: '12px 14px',
                        cursor: 'pointer',
                        background: isExpanded ? 'rgba(255,92,0,0.05)' : 'var(--surface)',
                        transition: 'background var(--transition)',
                      }}
                      {...activationProps(() => setExpandedAttention(isExpanded ? -1 : campaign.id), { expanded: isExpanded })}
                    >
                      {/* Row 1: chevron + agency name + view button */}
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <ChevronIcon size={10} style={{ color: 'var(--orange)', transition: 'transform 0.15s', transform: isExpanded ? 'rotate(90deg)' : 'none' }} />
                          <span style={{ fontWeight: 600, fontSize: 14 }}>{label}</span>
                        </div>
                        <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px' }}
                          onClick={e => { e.stopPropagation(); navigateCampaign(campaign.id); }}>
                          View →
                        </button>
                      </div>
                      {/* Row 2: meta + count + due date */}
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, paddingLeft: 17, flexWrap: 'wrap' }}>
                        <span style={{ fontSize: 12, color: 'var(--muted)' }}>{isAdmin && creator ? `${creator} · ` : ''}{month}</span>
                        <span style={{ fontSize: 10, fontWeight: 700, background: 'rgba(255,92,0,0.15)', color: 'var(--orange)', borderRadius: 2, padding: '1px 7px', letterSpacing: '0.5px' }}>
                          {items.length} {items.length === 1 ? 'item' : 'items'}
                        </span>
                        {earliest && <span style={{ fontSize: 12, color: 'var(--muted)' }}>Due {fmtDate(earliest.contracted_post_date)}</span>}
                      </div>
                    </div>
                    {isExpanded && (
                      <div>
                        {items.map(d => (
                          <div key={d.id}
                            style={{
                              padding: '10px 14px 10px 32px',
                              cursor: 'pointer',
                              borderTop: '1px solid var(--border)',
                              background: 'var(--surface2)',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                            }}
                            {...activationProps(() => navToDeliverable(campaign.id, d.id))}
                          >
                            <span style={{ fontSize: 13, color: 'var(--muted)' }}>{d.platform?.name}{d.deliverable_type?.name ? ` · ${d.deliverable_type.name}` : ''}</span>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
                              <Badge group="deliverable" statusId={d.draft_status_id} status={d.draft_status} />
                              {d.contracted_post_date && <span style={{ fontSize: 12, color: 'var(--muted)', whiteSpace: 'nowrap' }}>Due {fmtDate(d.contracted_post_date)}</span>}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* 2. Stats. Two facts only: what needs action, and what is running.
            Whichever matters more takes the first slot and the orange. There is
            no third number worth a tile here, and the pending-payment sections
            below already carry their own counts. */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 8, marginBottom: 20 }}>
          <div className="stat-card" style={{ padding: '14px 10px', ...(hasUrgent ? { background: 'rgba(255,92,0,0.07)', borderColor: 'rgba(255,92,0,0.22)' } : {}) }}>
            <div className="stat-value" style={{ color: 'var(--orange)', fontSize: hasUrgent ? 32 : 28 }}>
              {hasUrgent ? needsAttentionGrouped.length : active.length}
            </div>
            <div className="stat-label" style={{ fontSize: 10 }}>{hasUrgent ? 'Need Action' : 'Active'}</div>
          </div>
          <div className="stat-card" style={{ padding: '14px 10px' }}>
            <div className="stat-value" style={{ fontSize: 28, ...(hasUrgent ? {} : { color: 'var(--green)' }) }}>
              {hasUrgent ? active.length : 0}
            </div>
            <div className="stat-label" style={{ fontSize: 10 }}>{hasUrgent ? 'Active' : 'Need Action'}</div>
          </div>
        </div>

        {/* 3. In Progress: card list */}
        {active.length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
              <h2 className="card-title" style={{ margin: 0 }}>In Progress</h2>
              {isAdmin && <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('campaigns')}>View All →</button>}
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {active.map(c => {
                const dels    = c.campaign_deliverables || [];
                const posted  = dels.filter(d => delivText(d.draft_status_id) === 'Posted').length;
                const total   = dels.length;
                const isActive = campText(c.status_id) === 'Active';
                const next    = isActive
                  ? dels.filter(d => d.contracted_post_date && delivText(d.draft_status_id) !== 'Posted')
                        .sort((a, b) => a.contracted_post_date > b.contracted_post_date ? 1 : -1)[0]
                  : null;
                const dateLabel = isActive
                  ? (next ? fmtDate(next.contracted_post_date) : null)
                  : fmtDate(c.campaign_start_date);
                const ik = isInKind(c.invoices?.[0]?.is_in_kind);
                return (
                  <div
                    key={c.id}
                    {...activationProps(() => navigateCampaign(c.id))}
                    style={{
                      background: 'var(--surface)',
                      border: '1px solid var(--border)',
                      borderRadius: 6,
                      padding: '12px 14px',
                      cursor: 'pointer',
                    }}
                  >
                    {/* Row 1: campaign name + status */}
                    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, marginBottom: 6 }}>
                      <div style={{ minWidth: 0, flex: 1 }}>
                        <CampaignName campaign={c} />
                        {isAdmin && <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>{c.creator?.creator_name || c.creator?.full_name || ''}</div>}
                      </div>
                      <Badge group="campaign" statusId={c.status_id} status={c.status} />
                    </div>
                    {/* Row 2: posts progress + date + rate */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
                      {total > 0 && (
                        isActive ? (
                          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                            <span style={{ fontWeight: 500, fontSize: 12, color: posted === total ? 'var(--green)' : 'var(--white)' }}>{posted}/{total} posts</span>
                            <div style={{ width: 40, height: 3, background: 'var(--surface3)', borderRadius: 2 }}>
                              <div style={{ width: `${(posted / total) * 100}%`, height: '100%', background: posted === total ? 'var(--green)' : 'var(--orange)', borderRadius: 2 }} />
                            </div>
                          </div>
                        ) : (
                          <span style={{ fontSize: 12, color: 'var(--muted)' }}>{total} posts</span>
                        )
                      )}
                      {dateLabel && <span style={{ fontSize: 12, color: 'var(--muted)' }}>{isActive ? 'Due' : 'Starts'} {dateLabel}</span>}
                      <span style={{ fontSize: 12, color: 'var(--blue)', fontWeight: 600, marginLeft: 'auto' }}>
                        {ik ? <span style={{ color: 'var(--muted)' }}>In Kind</span> : fmtMoney(c.contracted_rate)}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* 4. Financial Summary */}
        <div style={{ marginBottom: 24 }}>
          <h2 className="card-title" style={{ marginBottom: 10 }}>Financial Summary</h2>
          <FinancialTable summaryRows={viewSummaryRows} rewardRows={viewRewardRows} period={period} isAdmin={isAdmin} fitContent />
        </div>

        {/* 5. Payments Pending: admin only, card list */}
        {isAdmin && (agencyPending.length > 0 || payoutsPending.length > 0) && (() => {
          const allPending = [...new Map(
            [...agencyPending, ...payoutsPending].map(c => [c.id, c])
          ).values()];
          return (
            <div style={{ marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
                <h2 className="card-title" style={{ margin: 0 }}>Payments Pending</h2>
                <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('payments')}>Payments →</button>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {allPending.map(c => {
                  const inv    = c.invoices?.[0];
                  const payout = c.creator_payouts?.[0];
                  return (
                    <div
                      key={c.id}
                      {...activationProps(() => setActiveView('payments'))}
                      style={{
                        background: 'var(--surface)',
                        border: '1px solid var(--border)',
                        borderRadius: 6,
                        padding: '12px 14px',
                        cursor: 'pointer',
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, marginBottom: 6 }}>
                        <div style={{ minWidth: 0, flex: 1 }}>
                          <CampaignName campaign={c} />
                          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>{c.creator?.creator_name || c.creator?.full_name || ''}</div>
                        </div>
                        <span style={{ fontSize: 13, color: 'var(--blue)', fontWeight: 600, whiteSpace: 'nowrap' }}>{fmtMoney(c.contracted_rate)}</span>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                        <Badge group="payment" statusId={inv?.payment_status_id} />
                        {payout ? <Badge group="payout" statusId={payout.payout_status_id} /> : <span style={{ fontSize: 11, color: 'var(--muted)' }}>No payout</span>}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })()}

        {/* 6. Platform Reach: reference rather than action, so it sits below everything that
          needs doing. Admin only: a creator comparing herself against the other one on her own
          dashboard is a different product decision than this screen is making. */}
      {isAdmin && (
        <div style={{ marginBottom: 24 }}>
          <h2 className="card-title" style={{ marginBottom: 10 }}>Platform Reach</h2>
          <PlatformReach />
        </div>
      )}

      {/* All clear */}
        {allClear && (
          <div style={{ padding: '48px 0', textAlign: 'center' }}>
            <div style={{ fontSize: 11, fontWeight: 600, letterSpacing: '2.5px', textTransform: 'uppercase', color: 'var(--muted)', marginBottom: 6 }}>
              {isAdmin ? 'All clear' : 'All caught up'}
            </div>
            <div style={{ fontSize: 12, color: 'var(--dim)' }}>
              {isAdmin ? 'No active campaigns or pending payments' : 'No immediate action needed'}
            </div>
          </div>
        )}

      </div>
    );
  }
  // ── Desktop render ─────────────────────────────────────────────────────────────

  return (
    <div className="page">

      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">{pageTitle}</h1>
          <div className="page-subtitle">{pageSubtitle}</div>
        </div>
        <div className="flex items-center gap-8">
          {isAdmin && creators.length > 0 && (
            <div className="flex gap-6">
              <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            </div>
          )}
          <PeriodSelect period={period} onChange={setPeriod} months={allMonths} style={{ padding: '5px 10px', fontSize: 12 }} />
        </div>
      </div>

      {/* 1. Needs Attention: top of page, no card wrapper */}
      {hasUrgent && (
        <div style={{ marginBottom: 28 }}>
          <div className="flex items-center justify-between" style={{ marginBottom: 10 }}>
            <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: '3.5px', textTransform: 'uppercase', color: 'var(--orange)' }}>
              {needsAttentionGrouped.length} {needsAttentionGrouped.length === 1 ? 'campaign needs' : 'campaigns need'} action
            </span>
            <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('campaigns')}>Go to Campaigns →</button>
          </div>
          <div style={{ border: '1px solid rgba(255,92,0,0.2)', borderRadius: 6, overflow: 'hidden' }}>
            {needsAttentionGrouped.map(({ campaign, items }, idx) => {
              const isExpanded = expandedAttention === null ? idx === 0 : expandedAttention === campaign.id;
              const earliest = items
                .filter(d => d.contracted_post_date)
                .sort((a, b) => a.contracted_post_date > b.contracted_post_date ? 1 : -1)[0];
              const { label, month } = campaignLabelParts(campaign);
              const creator = campaign.creator?.creator_name || campaign.creator?.full_name;
              return (
                <div key={campaign.id} style={{ borderBottom: idx < needsAttentionGrouped.length - 1 ? '1px solid var(--border)' : 'none' }}>
                  <div
                    className="flex items-center justify-between"
                    style={{
                      padding: '10px 14px',
                      cursor: 'pointer',
                      background: isExpanded ? 'rgba(255,92,0,0.05)' : 'var(--surface)',
                      transition: 'background var(--transition)',
                    }}
                    {...activationProps(() => setExpandedAttention(isExpanded ? -1 : campaign.id), { expanded: isExpanded })}
                  >
                    <div className="flex items-center gap-10">
                      <ChevronIcon size={10} style={{ color: 'var(--orange)', transition: 'transform 0.15s', transform: isExpanded ? 'rotate(90deg)' : 'none' }} />
                      <span style={{ fontWeight: 600, fontSize: 13 }}>{label}</span>
                      <span className="text-muted text-xs">{isAdmin && creator ? `${creator} · ` : ''}{month}</span>
                      <span style={{ fontSize: 10, fontWeight: 700, background: 'rgba(255,92,0,0.15)', color: 'var(--orange)', borderRadius: 2, padding: '1px 7px', letterSpacing: '0.5px' }}>
                        {items.length} {items.length === 1 ? 'item' : 'items'}
                      </span>
                    </div>
                    <div className="flex items-center gap-10">
                      {earliest && <span className="text-muted text-xs">Due {fmtDate(earliest.contracted_post_date)}</span>}
                      <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px' }}
                        onClick={e => { e.stopPropagation(); navigateCampaign(campaign.id); }}>
                        View →
                      </button>
                    </div>
                  </div>
                  {isExpanded && (
                    <div>
                      {items.map(d => (
                        <div key={d.id}
                          className="flex items-center justify-between"
                          style={{
                            padding: '7px 14px 7px 38px',
                            cursor: 'pointer',
                            borderTop: '1px solid var(--border)',
                            background: 'var(--surface2)',
                            transition: 'background var(--transition)',
                          }}
                          {...activationProps(() => navToDeliverable(campaign.id, d.id))}
                        >
                          <span className="text-muted text-sm">{d.platform?.name}{d.deliverable_type?.name ? ` · ${d.deliverable_type.name}` : ''}</span>
                          <div className="flex items-center gap-12">
                            <Badge group="deliverable" statusId={d.draft_status_id} status={d.draft_status} />
                            {d.contracted_post_date && <span className="text-sm text-muted">Due {fmtDate(d.contracted_post_date)}</span>}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. Stats. Two facts only: what needs action, and what is running.
          Whichever matters more takes the first slot and the orange. There is no
          third number worth a tile here, and the pending-payment sections below
          already carry their own counts. */}
      <div className="stats-row" style={{ marginBottom: 20 }}>
        <div className="stat-card" style={hasUrgent ? { background: 'rgba(255,92,0,0.07)', borderColor: 'rgba(255,92,0,0.22)' } : {}}>
          <div className="stat-value" style={{ color: 'var(--orange)', fontSize: hasUrgent ? 48 : 36 }}>
            {hasUrgent ? needsAttentionGrouped.length : active.length}
          </div>
          <div className="stat-label">{hasUrgent ? 'Need Action' : 'Active Campaigns'}</div>
        </div>
        <div className="stat-card">
          <div className="stat-value" style={hasUrgent ? undefined : { color: 'var(--green)' }}>
            {hasUrgent ? active.length : 0}
          </div>
          <div className="stat-label">{hasUrgent ? 'Active Campaigns' : 'Need Action'}</div>
        </div>
      </div>

      {/* 3. In Progress */}
      {active.length > 0 && (
        <div style={{ marginBottom: 24 }}>
          <div className="flex items-center justify-between mb-10">
            <h2 className="card-title" style={{ margin: 0 }}>In Progress</h2>
            {isAdmin && <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('campaigns')}>View All →</button>}
          </div>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th scope="col">Campaign</th>
                  {isAdmin && <th scope="col">Creator</th>}
                  <th scope="col">Status</th>
                  <th scope="col">Posts</th>
                  <th scope="col">Next Due / Starts</th>
                  <th scope="col">Rate</th>
                </tr>
              </thead>
              <tbody>
                {active.map(c => {
                  const dels    = c.campaign_deliverables || [];
                  const posted  = dels.filter(d => delivText(d.draft_status_id) === 'Posted').length;
                  const total   = dels.length;
                  const isActive = campText(c.status_id) === 'Active';
                  const next    = isActive
                    ? dels.filter(d => d.contracted_post_date && delivText(d.draft_status_id) !== 'Posted')
                          .sort((a, b) => a.contracted_post_date > b.contracted_post_date ? 1 : -1)[0]
                    : null;
                  const dateLabel = isActive
                    ? (next ? fmtDate(next.contracted_post_date) : null)
                    : fmtDate(c.campaign_start_date);
                  const ik = isInKind(c.invoices?.[0]?.is_in_kind);
                  return (
                    <tr key={c.id} {...activationProps(() => navigateCampaign(c.id))}>
                      <td><CampaignName campaign={c} /></td>
                      {isAdmin && <td>{c.creator?.creator_name || c.creator?.full_name || '—'}</td>}
                      <td><Badge group="campaign" statusId={c.status_id} /></td>
                      <td>
                        {total > 0 ? (
                          isActive ? (
                            <div className="flex items-center gap-8">
                              <span style={{ fontWeight: 500, color: posted === total ? 'var(--green)' : 'var(--white)', minWidth: 28 }}>{posted}/{total}</span>
                              <div style={{ width: 48, height: 3, background: 'var(--surface3)', borderRadius: 2 }}>
                                <div style={{ width: `${(posted / total) * 100}%`, height: '100%', background: posted === total ? 'var(--green)' : 'var(--orange)', borderRadius: 2 }} />
                              </div>
                            </div>
                          ) : (
                            <span className="text-muted">{total} posts</span>
                          )
                        ) : <span className="text-muted">—</span>}
                      </td>
                      <td>{dateLabel ? <span style={{ fontWeight: 500 }}>{dateLabel}</span> : <span className="text-muted">—</span>}</td>
                      <td style={{ color: 'var(--blue)', fontWeight: 600 }}>
                        {ik ? <span className="text-muted">In Kind</span> : fmtMoney(c.contracted_rate)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 4. Financial Summary */}
      <div style={{ marginBottom: 24 }}>
        <h2 className="card-title" style={{ marginBottom: 10 }}>Financial Summary</h2>
        <FinancialTable summaryRows={viewSummaryRows} rewardRows={viewRewardRows} period={period} isAdmin={isAdmin} />
      </div>

      {/* 5. Payments Pending: admin only */}
      {isAdmin && (agencyPending.length > 0 || payoutsPending.length > 0) && (() => {
        const allPending = [...new Map(
          [...agencyPending, ...payoutsPending].map(c => [c.id, c])
        ).values()];
        return (
          <div style={{ marginBottom: 16 }}>
            <div className="flex items-center justify-between mb-10">
              <h2 className="card-title" style={{ margin: 0 }}>Payments Pending</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setActiveView('payments')}>Go to Payments →</button>
            </div>
            <div className="table-wrap">
              <table>
                <thead>
                  <tr><th scope="col">Campaign</th><th scope="col">Creator</th><th scope="col">Rate</th><th scope="col">Invoice</th><th scope="col">Payout</th></tr>
                </thead>
                <tbody>
                  {allPending.map(c => {
                    const inv    = c.invoices?.[0];
                    const payout = c.creator_payouts?.[0];
                    return (
                      <tr key={c.id} {...activationProps(() => setActiveView('payments'))}>
                        <td><CampaignName campaign={c} /></td>
                        <td>{c.creator?.creator_name || c.creator?.full_name || '—'}</td>
                        <td style={{ color: 'var(--blue)', fontWeight: 600 }}>{fmtMoney(c.contracted_rate)}</td>
                        <td><Badge group="payment" statusId={inv?.payment_status_id} /></td>
                        <td>{payout ? <Badge group="payout" statusId={payout.payout_status_id} /> : <span className="text-muted text-xs">—</span>}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        );
      })()}

      {/* 6. Platform Reach: reference rather than action, so it sits below everything that
          needs doing. Admin only: a creator comparing herself against the other one on her own
          dashboard is a different product decision than this screen is making. */}
      {isAdmin && (
        <div style={{ marginBottom: 24 }}>
          <h2 className="card-title" style={{ marginBottom: 10 }}>Platform Reach</h2>
          <PlatformReach />
        </div>
      )}

      {/* All clear */}
      {allClear && (
        <div style={{ padding: '48px 0', textAlign: 'center' }}>
          <div style={{ fontSize: 11, fontWeight: 600, letterSpacing: '2.5px', textTransform: 'uppercase', color: 'var(--muted)', marginBottom: 6 }}>
            {isAdmin ? 'All clear' : 'All caught up'}
          </div>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>
            {isAdmin ? 'No active campaigns or pending payments' : 'No immediate action needed'}
          </div>
        </div>
      )}

    </div>
  );
}
