/**
 * components/shared/PlatformReach.js - every creator's platform figures, one block per metric.
 *
 * The same three figures the public creator card shows under "Main platforms", turned side by
 * side so two creators can be compared on one platform at a glance. Three small tables rather
 * than one wide one: each answers a single question (who is bigger, who is watched more, who is
 * engaged with more) with nothing else in the way.
 *
 * @invariant the figures are NOT computed here. `creator_platform_stats_view` computes them
 *            once, because the public site renders the same numbers and cannot import from this
 *            bundle. A second implementation here is how the two surfaces would start
 *            disagreeing. @see `utils/platformStats.js`
 */
import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtCompact, fmtPct } from '../../utils/format';
import { PlatformLogo } from './PlatformLogo';
import { useLoadState } from '../../hooks/useLoadState';
import ReadError from './ReadError';
import Skeleton from './Skeleton';
import EmptyState from './EmptyState';
import {
  METRICS, PLATFORM_LABEL, engagementRate, groupByCreator, isMeasured, platformsPresent,
} from '../../utils/platformStats';

/** One cell's text, or null when nothing about this creator on this platform is measured. */
function cellValue(row, metric) {
  if (!isMeasured(row)) return null;
  if (metric === 'followers') return row.followers == null ? null : fmtCompact(row.followers);
  if (metric === 'views') return fmtCompact(row.views);
  const rate = engagementRate(row);
  return rate == null ? null : fmtPct(rate);
}

export default function PlatformReach() {
  const [rows, setRows]   = useState([]);
  const [error, setError] = useState(null);
  const { loading, begin, end } = useLoadState();

  const load = useCallback(async () => {
    begin();
    // No platform named here on purpose: the view carries a `platform` column so the frontend
    // never reaches into a per-platform table. @see `.claude/rules/hub-data.md`
    const { data, error: e } = await supabase
      .from('creator_platform_stats_view')
      .select('display_name,platform,followers,views,interactions,eng_views');
    // A failed read must not fall through to the empty state: "no creators" is a positive
    // claim and this surface has no business making it on a refused query.
    setError(e || null);
    setRows(e ? [] : (data || []));
    end();
  }, [begin, end]);

  useEffect(() => { load(); }, [load]);

  if (loading) return <Skeleton label="Loading platform reach" bars={3} height={92} />;
  if (error)   return <ReadError error={error} label="platform reach" onRetry={load} />;

  const { creators, byCreator } = groupByCreator(rows);
  const platforms = platformsPresent(byCreator);
  if (!creators.length || !platforms.length) {
    return (
      <EmptyState
        variant="note"
        title="No platform accounts yet"
        text="Connect a creator's TikTok, YouTube or Instagram in Platform Setup and their figures appear here."
      />
    );
  }

  /* Three blocks side by side, not stacked. Eighteen figures do not need nine full-width rows:
     the earlier stacked version spent about 900px of height while leaving two thirds of the
     width empty, and the comparison it exists for was then off screen. The metric name is the
     corner cell rather than a heading above, which removes a row of chrome per block. */
  const cell = { padding: '3px 8px', fontSize: 12, lineHeight: 1.5 };
  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(238px, 1fr))', gap: 14 }}>
      {METRICS.map((metric) => (
        <table key={metric.key} style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr>
              <th scope="col" className="stat-label" style={{ ...cell, fontSize: 9, letterSpacing: '1.6px', textAlign: 'left' }}>
                {metric.label}
              </th>
              {creators.map((name) => (
                <th key={name} scope="col" className="stat-label" style={{ ...cell, fontSize: 9, letterSpacing: '1.6px', textAlign: 'right' }}>
                  {name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {platforms.map((p) => (
              <tr key={p}>
                <th scope="row" style={{ ...cell, fontWeight: 400, color: 'var(--dim)', textAlign: 'left' }}>
                  <span className="flex items-center" style={{ gap: 6 }}>
                    <PlatformLogo name={p} size={13} />
                    {PLATFORM_LABEL[p]}
                  </span>
                </th>
                {creators.map((name) => {
                  const value = cellValue(byCreator[name][p], metric.key);
                  return (
                    <td key={name} style={{ ...cell, textAlign: 'right' }}>
                      {value === null
                        ? <span className="text-muted" style={{ fontSize: 10 }}>{metric.absent}</span>
                        : <span className="stat-value" style={{ fontSize: 14 }}>{value}</span>}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      ))}
    </div>
  );
}
