/**
 * components/shared/HelpIcon.js: the inline (?) help affordance.
 *
 * Hover surfaces a small tooltip with the article's first sentence; click opens
 * the Help view by dispatching the window-level nys:help-open CustomEvent that
 * AdminDashboard / CreatorDashboard listen for. Styling lives in App.css under
 * .help-icon / .help-tooltip so it inherits theme tokens.
 *
 * @param {string} props.slug - help article slug.
 * @param {'admin'|'creator'} [props.audience] - which corpus to read and which dashboard to
 *        dispatch at. Defaults to the SHELL this icon is rendered inside, not to 'admin':
 *        most screens carrying a (?) are one shared component rendered in both dashboards,
 *        and `useHelpOpen` drops an event whose audience is not its own, so a fixed default
 *        made thirteen of these do nothing at all on the creator's screens.
 *        @see contexts/AudienceContext.js
 * @see components/shared/helpRegistry.js, components/shared/HelpView.js
 */
import React, { useState, useRef, useLayoutEffect } from 'react';
import { tooltipFor, getArticle } from './helpRegistry';
import { useAudience } from '../../contexts/AudienceContext';

export default function HelpIcon({ slug, audience: audienceProp }) {
  const shellAudience = useAudience();
  const audience = audienceProp || shellAudience;
  const [hover, setHover] = useState(false);
  const [align, setAlign] = useState('left');
  const wrapRef = useRef(null);
  const tip = tooltipFor(slug, audience);
  const article = getArticle(slug, audience);

  // Mirror the tooltip to the right edge if it would clip the viewport.
  useLayoutEffect(() => {
    if (!hover || !wrapRef.current) return;
    const r = wrapRef.current.getBoundingClientRect();
    const tooltipMax = 300;
    const wouldClip = r.left + tooltipMax > window.innerWidth - 8;
    setAlign(wouldClip ? 'right' : 'left');
  }, [hover]);

  function open(e) {
    e.preventDefault();
    e.stopPropagation();
    if (typeof window !== 'undefined' && typeof window.CustomEvent === 'function') {
      window.dispatchEvent(new window.CustomEvent('nys:help-open', { detail: { slug, audience } }));
    }
  }

  return (
    <span
      ref={wrapRef}
      className="help-icon-wrap"
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      <button
        type="button"
        onClick={open}
        aria-label={tip ? `Help: ${tip}` : 'Open help'}
        className="help-icon"
      >?</button>
      {hover && tip && (
        <span role="tooltip" className={`help-tooltip help-tooltip--${align}`}>
          {article && article.title && (
            <span className="help-tooltip-title">{article.title}</span>
          )}
          <span className="help-tooltip-rule" aria-hidden="true" />
          <span className="help-tooltip-body">{tip}</span>
          <span className="help-tooltip-cta">Click to read</span>
        </span>
      )}
    </span>
  );
}
