/**
 * components/shared/ReverseEntryModal.js. Confirm + execute a journal-entry reversal.
 *
 * The single shared reversal modal. Calls the SECURITY DEFINER
 * reverse_journal_entry(p_je_id, p_reason) RPC; the DB writes the offsetting
 * reversal JE (today's date) + the entry_reversed audit-log row. The original
 * is preserved and marked REVERSED, so corrections never mutate a posted JE.
 *
 * Used by: InvoiceForm, PayoutForm (lock-chip Reverse link), ExpensesPage (OOP
 * reverse), LedgerPage General Ledger row toolbar.
 *
 * @invariant a reason is required for every reversal (mirrors the RPC + audit log).
 * @invariant locked-period entries cannot be reversed (DB rejects; surfaced via humanizeError).
 * @see docs/MONEY.md (Patterns L/M/N reversals), reverse_journal_entry RPC
 */
import React, { useEffect, useRef, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtDate, fmtMoney } from '../../utils/format';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import Feedback from './Feedback';
import { humanizeError } from '../../utils/errors';
import Modal, { ModalClose } from './Modal';
import Field from './Field';

const REASON_MAX = 1000;

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[ReverseEntryModal]', ...args);
};

/**
 * @param {object} props
 * @param {{id, entry_date, description, source_type, reference?}} props.journalEntry - the JE to reverse
 * @param {object[]} [props.lines] - decorated entry lines ({account_code, account_name, debit, credit}) for the read-only preview
 * @param {function} props.onClose - dismiss without action
 * @param {function(string)} props.onReversed - called with the new reversal JE id after RPC success
 */
export default function ReverseEntryModal({ journalEntry, lines = [], onClose, onReversed }) {
  const [reason, setReason] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const reasonRef = useRef(null);
  const overlayRef = useRef(null);

  useEscapeKey(onClose, !submitting, overlayRef);

  useEffect(() => {
    requestAnimationFrame(() => reasonRef.current?.focus());
  }, []);

  if (!journalEntry) return null;

  async function handleSubmit() {
    const trimmed = reason.trim();
    if (!trimmed) {
      setError('A reason is required for every reversal.');
      reasonRef.current?.focus();
      return;
    }
    setSubmitting(true);
    setError('');
    const { data, error: rpcErr } = await supabase.rpc('reverse_journal_entry', {
      p_je_id: journalEntry.id,
      p_reason: trimmed.slice(0, REASON_MAX),
    });
    if (rpcErr) {
      log('rpc reverse_journal_entry', rpcErr);
      setError(humanizeError(rpcErr));
      setSubmitting(false);
      return;
    }
    setSubmitting(false);
    if (onReversed) onReversed(data);
    onClose();
  }

  const totalDebit  = lines.reduce((s, l) => s + (Number(l.debit)  || 0), 0);
  const totalCredit = lines.reduce((s, l) => s + (Number(l.credit) || 0), 0);

  return (
    <Modal
      title="REVERSE JOURNAL ENTRY"
      size="md"
      onClose={onClose}
      closeDisabled={submitting}
    >

        <div className="modal-body">
          <div style={{ marginBottom: 16, padding: '12px 14px', background: 'var(--surface2)', borderRadius: 6 }}>
            <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 6 }}>Entry being reversed</div>
            <div style={{ fontSize: 13, marginBottom: 4 }}><strong>{fmtDate(journalEntry.entry_date)}</strong>: {journalEntry.description || '—'}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>
              Source: {journalEntry.source_type || 'manual'}{journalEntry.reference ? ` · ${journalEntry.reference}` : ''}
            </div>
          </div>

          {lines.length > 0 ? (
            <div style={{ marginBottom: 16, fontSize: 12 }}>
              <div className="table-wrap">
                <table style={{ width: '100%' }}>
                  <thead>
                    <tr>
                      <th scope="col">Account</th>
                      <th scope="col" style={{ textAlign: 'right' }}>Debit</th>
                      <th scope="col" style={{ textAlign: 'right' }}>Credit</th>
                    </tr>
                  </thead>
                  <tbody>
                    {lines.map((l, i) => (
                      <tr key={l.id || i}>
                        <td>{[l.account_code, l.account_name].filter(Boolean).join('  ') || '—'}</td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.debit)  > 0 ? fmtMoney(l.debit)  : ''}</td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.credit) > 0 ? fmtMoney(l.credit) : ''}</td>
                      </tr>
                    ))}
                    <tr style={{ borderTop: '1px solid var(--border)', fontWeight: 700 }}>
                      <td>TOTALS</td>
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totalDebit)}</td>
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totalCredit)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          ) : null}

          <div style={{ marginBottom: 14, padding: '10px 12px', background: 'color-mix(in oklab, var(--orange) 8%, transparent)', borderLeft: '3px solid var(--orange)', fontSize: 12, color: 'var(--white)' }}>
            Reversal creates a new offsetting journal entry on today's date. The original entry is preserved and marked <strong>REVERSED</strong>: full audit trail. Locked-period entries cannot be reversed.
          </div>

          <Field label="Reason *" style={{ marginBottom: 0 }}>{(id) => (<>
            <textarea id={id}
              ref={reasonRef}
              className="form-textarea"
              rows={3}
              maxLength={REASON_MAX}
              value={reason}
              onChange={(e) => { setReason(e.target.value); setError(''); }}
              placeholder="Why is this entry being reversed? (Recorded in audit log.)"
              disabled={submitting}
            />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4, textAlign: 'right' }}>
              {reason.length}/{REASON_MAX}
            </div>
          </>)}</Field>

          {error ? <Feedback value={error} style={{ marginTop: 10 }} /> : null}
        </div>

        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={submitting}>Cancel</ModalClose>
          <button className="btn btn-danger" onClick={handleSubmit} disabled={submitting || !reason.trim()}>
            {submitting ? 'Reversing…' : 'Reverse entry'}
          </button>
        </div>
    </Modal>
  );
}
